INSERT INTO `roles` (`id`,`name`,`description`,`is_admin`,`is_system`,`all_sites`,`created_at`,`updated_at`) VALUES
(1,'Administrator','Everything in every module, including user accounts, roles, page access, the closing date, and the audit trail.',1,1,1,'2026-11-10 02:59:41',NULL),
(2,'Accountant','Financial (Chart of Accounts), Fixed Assets, Banking and reconciliation, the BIR Reports and Withholding Tax Table, all module reports, and the financial statements.',0,1,1,'2026-11-10 02:59:41',NULL),
(3,'A/R Clerk','Customers module transactions and the Customer and Receivables reports.',0,1,1,'2026-11-10 02:59:41',NULL),
(4,'A/P Clerk','Vendors module transactions, Pay Bills, advances to suppliers, the Vendors and Payables reports, and BIR Form 2307 for suppliers.',0,1,1,'2026-11-10 02:59:41',NULL),
(5,'Inventory Clerk','Items, sites, receiving, adjustments, assembly builds, disassembly and processing orders, stock counts, and inventory quantity reports.',0,1,1,'2026-11-10 02:59:41',NULL),
(6,'Sales Representative','Estimates, sales orders, and invoices, and the Sales reports.',0,1,1,'2026-11-10 02:59:41',NULL),
(7,'Cashier','POS sales, returns, and cash drops at the assigned terminal only.',0,1,0,'2026-11-10 02:59:41',NULL),
(8,'POS Supervisor','Everything a cashier can do, plus approving voids, refunds, price overrides, and large discounts, and running X- and Z-readings.',0,1,1,'2026-11-10 02:59:41',NULL),
(9,'Contracts - Bid & Compliance Officer','Barangay Contracts: finds opportunities, keeps the directory and the document vault, prepares bids, checklists and forms, and records submissions.',0,1,1,'2026-11-10 02:59:42',NULL),
(10,'Contracts - Approver (Management)','Barangay Contracts: approves bids, billing packs, change orders and forms within the approval limit, waives requirements, closes out and reopens contracts, and keeps the set-up lists.',0,1,1,'2026-11-10 02:59:42',NULL),
(11,'Contracts - Project Manager','Barangay Contracts: mobilizes awarded contracts, records deliveries and the entity\'s inspection, prepares change orders, tasks and progress reports.',0,1,1,'2026-11-10 02:59:42',NULL),
(12,'Contracts - Warehouse & Delivery','Barangay Contracts: records deliveries from the warehouse and files the signed delivery receipts.',0,1,1,'2026-11-10 02:59:42',NULL),
(13,'Contracts - Billing Officer','Barangay Contracts: prepares billing packs for accepted deliveries, issues the invoices once approved, submits the packs and follows up their acknowledgment.',0,1,1,'2026-11-10 02:59:42',NULL),
(14,'Contracts - Collection Officer','Barangay Contracts: records collections with the taxes withheld and deductions, returned checks, retention releases and the BIR Forms 2307 received.',0,1,1,'2026-11-10 02:59:42',NULL),
(15,'Auditor','View-only access to all transactions, reports, and the audit trail. Cannot create or change anything.',0,1,1,'2026-11-10 02:59:42',NULL);
