INSERT INTO `brgy_references` (`id`,`code`,`title`,`issuer`,`ref_type`,`issued_date`,`published_date`,`effective_date`,`url`,`applies_to`,`notes`,`last_reviewed`,`reviewed_by`,`is_active`,`created_at`,`updated_at`) VALUES
(1,'RA-12009','Republic Act No. 12009, New Government Procurement Act','Congress of the Philippines','law','2024-07-20',NULL,'2024-08-13','https://www.gppb.gov.ph/','All procurement of goods, infrastructure projects and consulting services by government entities, barangays included','Signed 20 July 2024; took effect 13 August 2024. Repealed RA 9184. Procurement started before the new rules applied follows the transitory provisions (see GPPB Resolution No. 05-2025).','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(2,'IRR-RA-12009','Implementing Rules and Regulations of RA 12009','Government Procurement Policy Board','irr',NULL,NULL,NULL,'https://www.gppb.gov.ph/','Procedures, procurement modes, documentary requirements, securities, contract implementation','Approved by the GPPB in February 2025 and published in the same month. Enter the effectivity date after checking the official copy.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(3,'GPPB-RES-05-2025','GPPB Resolution No. 05-2025 approving Circular No. 01-2025: guidance on Section 113 (Transitory Provision) in relation to Section 115 (Repealing Clause) of RA 12009 and its IRR','Government Procurement Policy Board','resolution','2025-09-18',NULL,NULL,'https://www.gppb.gov.ph/wp-content/uploads/2025/10/GPPB-Resolution-No.-05-2025.pdf','Which law and forms govern a procurement during the transition','Covers whether RA 9184 still applies to ongoing procurement, the use of RA 9184 forms, when the new standard procurement forms become mandatory, and a three-year transitory period counted from 14 May 2025.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(4,'GPPB-FORMS','GPPB Philippine Bidding Documents and standard procurement forms','Government Procurement Policy Board','other',NULL,NULL,NULL,'https://www.gppb.gov.ph/','Bid forms, omnibus sworn statement, bid / performance securing declarations, contract forms, price schedules','Use the version the procuring entity issued with its bidding documents or RFQ. The program keeps these as prescribed-form shells: paste the official text, do not reword it.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(5,'COA-2023-004','COA Circular No. 2023-004, updated documentary requirements for common government transactions','Commission on Audit','circular','2023-06-14',NULL,NULL,'https://www.coa.gov.ph/','Supporting papers the entity needs to pay a supplier or contractor','Amends COA Circular No. 2012-001. Use it to build the billing pack the entity\'s accountant and auditor will look for.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(6,'BIR-RR-7-2024','Revenue Regulations No. 7-2024 (invoicing under the Ease of Paying Taxes Act)','Bureau of Internal Revenue','regulation',NULL,'2024-04-12','2024-04-27','https://www.bir.gov.ph/','Sales invoice as the primary document for sales of goods and services','Official receipts may still be used as supplementary documents marked \"This document is not valid for claim of input tax.\" A document printed by this program is not by itself a BIR-registered invoice.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(7,'BIR-RR-11-2024','Revenue Regulations No. 11-2024 (amending RR 7-2024: registration and invoicing transition)','Bureau of Internal Revenue','regulation','2024-06-13',NULL,NULL,'https://www.bir.gov.ph/','Transition for invoices and receipts','Read with RR 7-2024 and the later BIR issuances, including e-invoicing guidance.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(8,'BIR-RR-11-2018','Revenue Regulations No. 11-2018 (withholding tax rates, including government payors)','Bureau of Internal Revenue','regulation',NULL,NULL,NULL,'https://www.bir.gov.ph/','Income tax and VAT withheld by government buyers (BIR Reports > Withholding Tax Table)','Rates are kept on the Withholding Tax Table, never in the program; check them against the current rules and the entity\'s Form 2307.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(9,'RA-9184','Republic Act No. 9184, Government Procurement Reform Act (repealed)','Congress of the Philippines','law','2003-01-10',NULL,NULL,'https://www.gppb.gov.ph/','Procurement started before the RA 12009 rules applied','Repealed by RA 12009; still governs transition cases as the transitory provisions allow.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL),
(10,'RA-10173','Republic Act No. 10173, Data Privacy Act of 2012','Congress of the Philippines','law','2012-08-15',NULL,NULL,'https://www.privacy.gov.ph/','Personal information of officials and contact persons, documents kept in the vault','Keep only what is needed, limit access (confidential documents), and log every download.','2026-11-10',NULL,1,'2026-11-10 02:59:42',NULL);
