INSERT INTO `brgy_templates` (`id`,`code`,`name`,`category`,`stage`,`doc_type`,`description`,`body`,`paper`,`orientation`,`is_prescribed`,`official_source`,`official_version`,`required_fields`,`needs_approval`,`print_mode`,`layout_json`,`positions_json`,`bg_file`,`version_no`,`sort_order`,`is_active`,`lock_version`,`created_by`,`created_at`,`updated_by`,`updated_at`) VALUES
(1,'cover_letter','Cover letter: submission of bid / quotation','letter','bid','cover_letter','Covering letter of the bid or quotation, listing what is enclosed.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Submission of bid / quotation for {{project.title}} ({{project.reference_no}})</b></p><p>Dear Sir / Madam:</p><p>In response to your invitation, {{company.name}} respectfully submits its bid / quotation for <b>{{project.title}}</b> in the total amount of <b>{{project.bid_amount}}</b> ({{project.bid_amount_words}}), inclusive of all applicable taxes, under the terms and specifications of your request.</p><p>Enclosed are the documents your request asks for, as listed in our checklist:</p>{{requirements.table}}<p>Our offer is valid for the period stated in your bidding documents. For clarifications, please contact the undersigned at {{company.phone}} or {{company.email}}.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'signatory.name,entity.name',1,'layout',NULL,NULL,NULL,1,10,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(2,'company_profile','Company profile','proforma','bid','company_profile','Short profile of the company for bid and eligibility envelopes.','<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">COMPANY PROFILE</h2><table class=\"ft\"><tbody><tr><td style=\"width:34%\">Registered name</td><td><b>{{company.name}}</b></td></tr><tr><td>Business address</td><td>{{company.address}}</td></tr><tr><td>Registration</td><td>{{company.reg_no}}</td></tr><tr><td>TIN / tax status</td><td>{{company.tin}}   ({{company.vat_status}})</td></tr><tr><td>PhilGEPS registration</td><td>{{company.philgeps_no}}   {{company.philgeps_class}}</td></tr><tr><td>Contact</td><td>{{company.phone}}   {{company.email}}</td></tr><tr><td>Authorized representative</td><td>{{signatory.name}}, {{signatory.position}}</td></tr></tbody></table><h3>Lines of business</h3><p>Supply and delivery of office, school, medical and household supplies, IT equipment and furniture; general services (janitorial, maintenance, repairs); and, through its licensed construction arm, minor infrastructure works for barangays and local government units.</p><h3>Facilities and people</h3><p>[Describe the warehouse, delivery vehicles, technical staff and the after-sales service offered.]</p><h3>Major government clients</h3><p>[List recent contracts: entity, project, amount, date completed.]</p>','A4','portrait',0,NULL,NULL,'company.name',1,'layout',NULL,NULL,NULL,1,20,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(3,'quotation','Price quotation','proforma','bid','quotation','Company price quotation with the price schedule (when the entity has no form of its own).','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PRICE QUOTATION</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>We offer to supply the following under the terms of your request for quotation:</p>{{lines.table}}<p><b>Total amount: {{lines.total}}</b> ({{lines.total_words}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Delivery period</td><td>{{project.delivery_days}} from receipt of the purchase order / notice to proceed</td></tr><tr><td>Delivery site</td><td>{{project.delivery_site}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr><tr><td>Payment terms</td><td>{{project.payment_terms}}</td></tr><tr><td>Validity of the offer</td><td>As stated in the RFQ</td></tr></tbody></table><p>Prices include all applicable taxes, delivery and handling. We confirm that the items offered comply with the specifications stated in your request.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'signatory.name,project.title',1,'layout','{\"signatories\":[{\"lead\":\"Submitted by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,30,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(4,'price_schedule','Price schedule / bill of quantities','proforma','bid','price_schedule','Price schedule from the project lines (use the entity\'s own schedule form when its documents prescribe one).','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PRICE SCHEDULE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p></p>{{lines.table}}<p><b>Total bid price: {{lines.total}}</b><br>({{lines.total_words}})</p><p>Name of bidder: <b>{{company.name}}</b><br>Signature of the authorized representative:</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout','{\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,40,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(5,'technical_proposal','Technical proposal and statement of compliance','proforma','bid','technical_proposal','Item-by-item statement of compliance with the technical specifications.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">TECHNICAL PROPOSAL AND STATEMENT OF COMPLIANCE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>We state below, item by item, our compliance with the technical specifications. Where \"Comply\" is stated, the offer meets or exceeds the requirement; supporting brochures and data sheets are attached.</p><table class=\"ft\"><thead><tr><th style=\"width:6%\">Item</th><th>Specification required</th><th style=\"width:30%\">Offer (brand, model, specification)</th><th style=\"width:12%\">Statement</th></tr></thead><tbody><tr><td>1</td><td>{{project.specs}}</td><td>[Brand / model offered]</td><td>Comply</td></tr></tbody></table><p><b>Delivery:</b> {{project.delivery_days}} at {{project.delivery_site}}. <b>Warranty:</b> {{project.warranty_months}}.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout','{\"signatories\":[{\"lead\":\"Certified correct:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,50,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(6,'method_statement','Method statement (works / services)','proforma','bid','method_statement','How the works or services will be carried out: sequence, resources, safety and quality control.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">METHOD STATEMENT</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><h3>1. Scope</h3><p>{{project.specs}}</p><h3>2. Mobilization</h3><p>[Site set-up, permits, coordination with the barangay and the end-user ({{project.end_user}}).]</p><h3>3. Sequence of work</h3><ol><li>[Activity]</li><li>[Activity]</li><li>[Activity]</li></ol><h3>4. Manpower and equipment</h3><p>[List of key personnel and equipment.]</p><h3>5. Quality control and testing</h3><p>[Tests, inspections and hold points; acceptance by the entity\'s inspection committee.]</p><h3>6. Safety and environment</h3><p>[Safety plan, signage, housekeeping, disposal.]</p><h3>7. Schedule</h3><p>Completion within {{project.delivery_days}} from the notice to proceed.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout','{\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,60,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(7,'implementation_schedule','Implementation / delivery schedule','proforma','bid','schedule','Schedule of deliveries or activities over the contract period.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">IMPLEMENTATION / DELIVERY SCHEDULE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><table class=\"ft\"><thead><tr><th style=\"width:6%\">No.</th><th>Activity / delivery</th><th style=\"width:18%\">Start</th><th style=\"width:18%\">Finish</th><th style=\"width:16%\">Weight %</th></tr></thead><tbody><tr><td>1</td><td>Mobilization / receipt of PO or NTP</td><td>Day 1</td><td>Day 3</td><td>5</td></tr><tr><td>2</td><td>[Delivery / work package]</td><td></td><td></td><td></td></tr><tr><td>3</td><td>Inspection and acceptance</td><td></td><td></td><td></td></tr></tbody></table><p>Total contract period: {{project.delivery_days}}.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout','{\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,70,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(8,'supply_proposal','Supply and services proposal','proforma','bid','proposal','Narrative proposal for supply and related services (training, installation, after-sales).','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SUPPLY AND SERVICES PROPOSAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>{{company.name}} proposes to supply and deliver the items below, together with the related services described, for <b>{{lines.total}}</b>.</p>{{lines.table}}<h3>Related services</h3><ul><li>Delivery, unloading and installation at {{project.delivery_site}}</li><li>Orientation of the end-users</li><li>Warranty service: {{project.warranty_months}}</li></ul><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout',NULL,NULL,NULL,1,80,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(9,'scope_of_work','Scope-of-work proposal','proforma','bid','proposal','Proposal for services or works: scope, deliverables, exclusions and price.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SCOPE-OF-WORK PROPOSAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><h3>Scope of work</h3><p>{{project.specs}}</p><h3>Deliverables</h3><ul><li>[Deliverable]</li><li>[Deliverable]</li></ul><h3>Exclusions</h3><p>[Items not included.]</p><h3>Price</h3>{{lines.table}}<p>Duration: {{project.delivery_days}}. Payment: {{project.payment_terms}}.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout',NULL,NULL,NULL,1,90,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(10,'supplier_request','Request for quotation to a supplier / subcontractor','internal','internal','supplier_request','Asks suppliers and subcontractors for prices and their certifications (kept apart from the sale to the barangay).','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">REQUEST FOR QUOTATION (SUPPLIER / SUBCONTRACTOR)</h2><p>To: [Supplier / subcontractor]<br>Address: [Address]</p><p>We are preparing an offer for <b>{{project.title}}</b> for {{entity.name}}. Please quote your best price and delivery for the following, valid for at least 30 days:</p>{{lines.table}}<p>Please include with your quotation: your business permit, BIR registration, product certifications or licenses, warranty terms and delivery lead time. Prices to us are separate from our prices to the procuring entity; this request does not disclose the entity\'s budget.</p><p>Reply to {{project.preparer}} at {{company.email}} by [date].</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.title',1,'layout','{\"signatories\":[{\"lead\":\"Requested by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,100,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(11,'bid_approval_sheet','Internal bid approval sheet','internal','internal','internal','Go / no-go, costing and margin, compliance, and the sign-off of the preparer, checker and approver before submission.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">INTERNAL BID APPROVAL SHEET</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project no.</td><td>{{project.no}}</td></tr><tr><td>Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode / law</td><td>{{project.mode}}, {{project.regime}}</td></tr><tr><td>ABC</td><td>{{project.abc}}</td></tr><tr><td>Bid amount</td><td><b>{{project.bid_amount}}</b></td></tr><tr><td>Bid deadline</td><td>{{project.bid_deadline}}</td></tr></tbody></table><h3>Costing and margin (confidential)</h3>{{costing.table}}<h3>Compliance checklist</h3>{{requirements.table}}<h3>Remarks</h3><p>[Risks, assumptions, supplier quotations relied on, payment record of the entity.]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.preparer}}</div><div>Prepared by</div></td><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.checker}}</div><div>Checked by</div></td><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>','A4','portrait',0,NULL,NULL,'project.no',1,'layout',NULL,NULL,NULL,1,110,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(12,'contract_review_sheet','Contract review sheet','internal','award','internal','Review of the notice of award, purchase order or contract against the bid before signing.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">CONTRACT REVIEW SHEET</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b> ({{project.no}})</td></tr><tr><td>Notice of award</td><td>{{project.noa_ref}}, {{project.noa_date}}</td></tr><tr><td>Contract / PO no.</td><td>{{project.contract_ref}}</td></tr><tr><td>Amount awarded</td><td>{{project.contract_amount}}</td></tr><tr><td>Delivery / completion</td><td>{{project.delivery_days}}; due {{project.due_date}}</td></tr><tr><td>Retention</td><td>{{project.retention_pct}}</td></tr><tr><td>Liquidated damages</td><td>{{project.ld_rate}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr><tr><td>Payment terms</td><td>{{project.payment_terms}}</td></tr></tbody></table><h3>Checks</h3><table class=\"ft\"><thead><tr><th>Point</th><th style=\"width:16%\">OK</th><th style=\"width:36%\">Remarks</th></tr></thead><tbody><tr><td>Items, quantities and prices agree with the approved bid</td><td></td><td></td></tr><tr><td>Delivery period and site can be met</td><td></td><td></td></tr><tr><td>Performance security / warranty requirements understood</td><td></td><td></td></tr><tr><td>Billing documents and payment terms understood</td><td></td><td></td></tr><tr><td>Taxes to be withheld by the entity noted</td><td></td><td></td></tr></tbody></table><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.checker}}</div><div>Reviewed by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>','A4','portrait',0,NULL,NULL,'project.no',1,'layout',NULL,NULL,NULL,1,120,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(13,'handover_memo','Project handover memo (sales to operations)','internal','award','internal','Hands the awarded contract to the project manager and warehouse with what was promised.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PROJECT HANDOVER MEMO</h2><p><b>To:</b> {{project.pm}}, Project Manager; Warehouse and Delivery<br><b>From:</b> {{project.preparer}}<br><b>Re:</b> {{project.title}} ({{project.no}})</p><p>The contract below was awarded to the company by {{entity.name}} (notice of award {{project.noa_ref}}, {{project.noa_date}}). Please mobilize as follows:</p>{{lines.contract_table}}<table class=\"ft\"><tbody><tr><td style=\"width:32%\">Delivery site</td><td>{{project.delivery_site}}</td></tr><tr><td>Due</td><td>{{project.due_date}}</td></tr><tr><td>End-user</td><td>{{project.end_user}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr></tbody></table><p>Deliveries are recorded on Deliveries &amp; Acceptance; the signed delivery receipt and the inspection and acceptance report are filed in the Document Vault, as billing depends on them.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.preparer}}</div><div>Handed over by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.pm}}</div><div>Received by</div></td></tr></table>','A4','portrait',0,NULL,NULL,'project.no',1,'layout',NULL,NULL,NULL,1,130,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(14,'delivery_receipt','Delivery receipt','proforma','delivery','dr','Delivery receipt of the goods delivered, for the entity\'s signature.','<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">DELIVERY RECEIPT</h2><table class=\"ft\"><tbody><tr><td style=\"width:24%\">DR no.</td><td><b>{{delivery.no}}</b></td><td style=\"width:20%\">Date</td><td>{{delivery.date}}</td></tr><tr><td>Delivered to</td><td colspan=\"3\">{{entity.name}}, {{delivery.to}}</td></tr><tr><td>Project</td><td colspan=\"3\">{{project.title}} (contract / PO {{project.contract_ref}})</td></tr></tbody></table><p></p>{{delivery.table}}<p>Received the above items in good order and condition, subject to inspection and acceptance by the entity.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Delivered by ({{company.name}})</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{delivery.received_by}} {{delivery.received_position}}</div><div>Received by (name, position, date)</div></td></tr></table>','A4','portrait',0,NULL,NULL,'delivery.no,entity.name',1,'layout',NULL,NULL,NULL,1,140,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(15,'accomplishment_report','Service / accomplishment report','proforma','delivery','accomplishment','Report of services rendered or work accomplished for the period, for the end-user\'s certification.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SERVICE / ACCOMPLISHMENT REPORT</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>Period covered: [from] to [to]</p>{{delivery.table}}<h3>Work done</h3><p>[Describe the services rendered / work accomplished, with dates.]</p><h3>Issues and actions</h3><p>[None]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.pm}}</div><div>Submitted by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{entity.end_user}}</div><div>Certified by the end-user</div></td></tr></table>','A4','portrait',0,NULL,NULL,'project.title',1,'layout',NULL,NULL,NULL,1,150,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(16,'transmittal','Transmittal letter','letter','billing','transmittal','Transmits documents to the entity and asks for the receiving copy.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">TRANSMITTAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Re: {{project.title}}</b></p><p>We transmit the following documents for your appropriate action:</p><table class=\"ft\"><thead><tr><th style=\"width:6%\">No.</th><th>Document</th><th style=\"width:16%\">Copies</th></tr></thead><tbody><tr><td>1</td><td>[Document]</td><td>1</td></tr><tr><td>2</td><td>[Document]</td><td>1</td></tr></tbody></table><p>Kindly acknowledge receipt by signing below.</p><div>{{signatories}}</div><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Received by (name, position)</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Date and time received</div></td></tr></table>','A4','portrait',0,NULL,NULL,'entity.name',1,'layout',NULL,NULL,NULL,1,160,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(17,'billing_cover_letter','Billing cover letter / request for payment','letter','billing','billing_letter','Requests payment of a billing, listing the pack enclosed.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Request for payment, {{billing.type}} {{billing.no}} for {{project.title}}</b></p><p>Dear Sir / Madam:</p><p>We respectfully request payment of <b>{{billing.gross}}</b> ({{billing.gross_words}}) for the deliveries / services accepted under {{project.contract_ref}}, as detailed below:</p>{{billing.table}}<p>Enclosed are our sales invoice no. {{billing.si_no}}, the statement of account, and the signed delivery and inspection and acceptance documents.</p><p>Payment may be made by check payable to <b>{{company.name}}</b> or by credit to: {{company.bank_details}}. Kindly furnish us BIR Form 2307 for the taxes withheld.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'billing.no,signatory.name',1,'layout',NULL,NULL,NULL,1,170,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(18,'statement_of_account','Statement of account','proforma','billing','soa','Billings, payments (with the taxes withheld and deductions) and the balance of the contract.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">STATEMENT OF ACCOUNT</h2><table class=\"ft\"><tbody><tr><td style=\"width:24%\">Bill to</td><td><b>{{entity.name}}</b><br>{{entity.address}}</td></tr><tr><td>Project</td><td>{{project.title}} ({{project.no}})</td></tr><tr><td>Contract / PO</td><td>{{project.contract_ref}}, {{project.contract_amount}}</td></tr></tbody></table><p></p>{{soa.table}}<p>Please make payment to {{company.name}}: {{company.bank_details}}.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Prepared by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>Noted by</div></td></tr></table>','A4','portrait',0,NULL,NULL,'entity.name',1,'layout',NULL,NULL,NULL,1,180,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(19,'collection_followup','Collection follow-up letter','letter','collection','followup_letter','Courteous follow-up of a billing that is due.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.treasurer}}</b><br>Treasurer<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Subject: Follow-up of payment, {{project.title}}</b></p><p>Dear Sir / Madam:</p><p>May we respectfully follow up the payment of our billing for the above project, which has been accepted and is now due. Our records show the following:</p>{{soa.table}}<p>Should any document be lacking for the processing of the payment, please let us know so we can provide it at once.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name',1,'layout',NULL,NULL,NULL,1,190,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(20,'acknowledgment_receipt','Acknowledgment receipt (supplementary)','receipt','collection','or_ar','Acknowledges a payment received. A supplementary document only: the sales invoice remains the primary document.','<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">ACKNOWLEDGMENT RECEIPT</h2><table class=\"ft\"><tbody><tr><td style=\"width:26%\">No.</td><td>{{collection.no}}</td><td style=\"width:16%\">Date</td><td>{{collection.date}}</td></tr></tbody></table><p>Received from <b>{{entity.name}}</b> the amount of <b>{{collection.amount_words}} ({{collection.amount}})</b> by {{collection.reference}}, in payment of billing {{billing.no}} (sales invoice no. {{billing.si_no}}) for {{project.title}}.</p>{{collection.table}}<p style=\"margin-top:14px;font-weight:bold;text-align:center;border:1px solid #000;padding:6px\">THIS DOCUMENT IS NOT VALID FOR CLAIM OF INPUT TAX.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:100%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Received by (cashier / collector)</div></td></tr></table>','A4','portrait',0,NULL,NULL,'collection.no',1,'layout',NULL,NULL,NULL,1,200,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(21,'reconciliation_sheet','Contract reconciliation sheet','internal','collection','internal','Reconciles the contract, deliveries, billings, collections, taxes, retention and the ledger.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">CONTRACT RECONCILIATION SHEET</h2><p><b>{{project.title}}</b> ({{project.no}}), {{entity.name}}</p>{{closeout.table}}<h3>Statement of account</h3>{{soa.table}}<h3>Differences and actions</h3><p>[None]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Prepared by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Checked by (accounting)</div></td></tr></table>','A4','portrait',0,NULL,NULL,'project.no',1,'layout',NULL,NULL,NULL,1,210,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(22,'closeout_summary','Project completion and closeout summary','internal','closeout','closeout','Final figures, papers on file, warranty and lessons learned at closeout.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PROJECT COMPLETION AND CLOSEOUT SUMMARY</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b> ({{project.no}})</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Contract</td><td>{{project.contract_ref}}, NOA {{project.noa_ref}}</td></tr><tr><td>Warranty until</td><td>{{project.warranty_until}}</td></tr></tbody></table><h3>Final figures</h3>{{closeout.table}}<h3>Papers on file</h3>{{requirements.all_table}}<h3>Lessons learned</h3><p>[What went well, what to change next time.]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.pm}}</div><div>Prepared by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>','A4','portrait',0,NULL,NULL,'project.no',1,'layout',NULL,NULL,NULL,1,220,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(23,'contract_goods','Contract agreement: supply and delivery of goods (proforma)','contract','contract','contract','Reusable contract for goods: parties, contract documents, scope, price, delivery, inspection, payment, retention, warranty, liquidated damages, changes, termination.','<h2 style=\"text-align:center\">CONTRACT AGREEMENT<br><span style=\"font-size:12pt\">Supply and Delivery of Goods</span></h2><p style=\"font-size:9pt;border:1px solid #999;padding:6px\"><i>Company proforma. Where the ENTITY\'s bidding documents prescribe a contract form or general and special conditions of contract, those govern; this proforma is used only as the ENTITY accepts it. Review with counsel before signing.</i></p><p>This Agreement is made on {{project.contract_date}} at {{entity.city}}, {{entity.province}}, by and between:</p><p><b>{{entity.name}}</b>, a government entity with office at {{entity.address}}, represented by <b>{{entity.head_name}}</b>, {{entity.head_position}} (the \"ENTITY\"); and</p><p><b>{{company.name}}</b>, {{company.reg_no}}, with business address at {{company.address}}, TIN {{company.tin}}, represented by <b>{{signatory.name}}</b>, {{signatory.position}} (the \"SUPPLIER\");</p><p><b>WHEREAS</b>, the ENTITY procured <b>{{project.title}}</b> ({{project.reference_no}}) through {{project.mode}} under {{project.regime}}, funded by {{project.funding_source}};</p><p><b>WHEREAS</b>, the ENTITY awarded the contract to the SUPPLIER by Notice of Award {{project.noa_ref}} dated {{project.noa_date}};</p><p><b>NOW, THEREFORE</b>, the parties agree as follows:</p><p><b>1. Contract documents.</b> The following form part of this Agreement and are read together, in this order of precedence: this Agreement; the Notice of Award; the purchase order or notice to proceed; the bid / quotation of the SUPPLIER with its price schedule; the technical specifications or terms of reference; and the general and special conditions issued by the ENTITY, if any.</p><p><b>2. Scope.</b> The SUPPLIER shall supply and deliver the goods as listed below:</p>{{lines.contract_table}}<p><b>3. Contract price.</b> The contract price is <b>{{project.contract_amount}}</b> ({{project.contract_amount_words}}), inclusive of all applicable taxes, duties, delivery and other charges. The ENTITY shall withhold the taxes required by law and issue BIR Form 2307 for them.</p><p><b>4. Period and place.</b> The SUPPLIER shall deliver the goods to {{project.delivery_site}} within {{project.delivery_days}} from receipt of the purchase order / notice to proceed, on or before {{project.due_date}}.</p><p><b>5. Inspection and acceptance.</b> The ENTITY, through its inspection and acceptance committee, shall inspect the deliveries or work and issue its inspection and acceptance report. Items rejected shall be replaced or corrected by the SUPPLIER at its cost within the period the ENTITY sets.</p><p><b>6. Payment.</b> {{project.payment_terms}}. Each billing shall be supported by the sales invoice, statement of account, signed delivery receipts or accomplishment reports and the inspection and acceptance report. A retention of {{project.retention_pct}} of each payment, where applicable, shall be released after the warranty period upon the ENTITY\'s final acceptance.</p><p><b>7. Warranty.</b> The SUPPLIER warrants the goods / work against defects for {{project.warranty_months}} from acceptance and shall correct any defect reported within that period at its cost.</p><p><b>8. Liquidated damages.</b> For each day of delay beyond the agreed period not caused by the ENTITY or by force majeure, the SUPPLIER shall pay liquidated damages of {{project.ld_rate}} of the cost of the unperformed portion, deductible from any amount due.</p><p><b>9. Performance security.</b> Where required by the contract documents, the SUPPLIER shall post the performance security in the form and amount stated there, valid until final acceptance.</p><p><b>10. Changes.</b> No change in quantity, scope, price or period is valid unless approved in writing by the ENTITY\'s authorized official in accordance with the applicable procurement rules.</p><p><b>11. Termination.</b> Either party may terminate this Agreement on the grounds and through the procedures provided by the applicable procurement law, its implementing rules and the contract documents.</p><p><b>12. Governing law and venue.</b> This Agreement is governed by the laws of the Philippines. Disputes shall first be settled amicably; failing that, through the dispute resolution provided by the applicable procurement rules, and the courts of the place of the ENTITY.</p><p><b>13. Entire agreement.</b> This Agreement and the contract documents contain the whole agreement of the parties; amendments are valid only in writing and signed by both.</p><p>IN WITNESS WHEREOF, the parties have signed this Agreement on the date and at the place first written above.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{entity.head_name}}</div><div>For the ENTITY: {{entity.head_position}}</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>For the SUPPLIER: {{signatory.position}}</div></td></tr></table><p style=\"margin-top:14px\">Signed in the presence of:</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Witness</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Witness</div></td></tr></table><h3 style=\"margin-top:20px\">ACKNOWLEDGMENT</h3><p>Republic of the Philippines )<br>________________________ ) S.S.</p><p>[Notarial acknowledgment to be completed by the notary public.]</p>','Folio','portrait',0,NULL,NULL,'entity.head_name,signatory.name,project.contract_amount',1,'layout',NULL,NULL,NULL,1,230,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(24,'contract_services','Contract agreement: general services (proforma)','contract','contract','contract','Reusable contract for janitorial, maintenance, repair, catering and other general services.','<h2 style=\"text-align:center\">CONTRACT AGREEMENT<br><span style=\"font-size:12pt\">General Services</span></h2><p style=\"font-size:9pt;border:1px solid #999;padding:6px\"><i>Company proforma. Where the ENTITY\'s bidding documents prescribe a contract form or general and special conditions of contract, those govern; this proforma is used only as the ENTITY accepts it. Review with counsel before signing.</i></p><p>This Agreement is made on {{project.contract_date}} at {{entity.city}}, {{entity.province}}, by and between:</p><p><b>{{entity.name}}</b>, a government entity with office at {{entity.address}}, represented by <b>{{entity.head_name}}</b>, {{entity.head_position}} (the \"ENTITY\"); and</p><p><b>{{company.name}}</b>, {{company.reg_no}}, with business address at {{company.address}}, TIN {{company.tin}}, represented by <b>{{signatory.name}}</b>, {{signatory.position}} (the \"SUPPLIER\");</p><p><b>WHEREAS</b>, the ENTITY procured <b>{{project.title}}</b> ({{project.reference_no}}) through {{project.mode}} under {{project.regime}}, funded by {{project.funding_source}};</p><p><b>WHEREAS</b>, the ENTITY awarded the contract to the SUPPLIER by Notice of Award {{project.noa_ref}} dated {{project.noa_date}};</p><p><b>NOW, THEREFORE</b>, the parties agree as follows:</p><p><b>1. Contract documents.</b> The following form part of this Agreement and are read together, in this order of precedence: this Agreement; the Notice of Award; the purchase order or notice to proceed; the bid / quotation of the SUPPLIER with its price schedule; the technical specifications or terms of reference; and the general and special conditions issued by the ENTITY, if any.</p><p><b>2. Scope.</b> The SUPPLIER shall render the services as listed below:</p>{{lines.contract_table}}<p><b>3. Contract price.</b> The contract price is <b>{{project.contract_amount}}</b> ({{project.contract_amount_words}}), inclusive of all applicable taxes, duties, delivery and other charges. The ENTITY shall withhold the taxes required by law and issue BIR Form 2307 for them.</p><p><b>4. Period and place.</b> The services shall be rendered at {{project.delivery_site}} from {{project.start_date}} for {{project.delivery_days}}, under the schedule in the terms of reference. Each period\'s services are certified by the end-user ({{project.end_user}}) through the accomplishment report.</p><p><b>5. Inspection and acceptance.</b> The ENTITY, through its inspection and acceptance committee, shall inspect the deliveries or work and issue its inspection and acceptance report. Items rejected shall be replaced or corrected by the SUPPLIER at its cost within the period the ENTITY sets.</p><p><b>6. Payment.</b> {{project.payment_terms}}. Each billing shall be supported by the sales invoice, statement of account, signed delivery receipts or accomplishment reports and the inspection and acceptance report. A retention of {{project.retention_pct}} of each payment, where applicable, shall be released after the warranty period upon the ENTITY\'s final acceptance.</p><p><b>7. Warranty.</b> The SUPPLIER warrants the goods / work against defects for {{project.warranty_months}} from acceptance and shall correct any defect reported within that period at its cost.</p><p><b>8. Liquidated damages.</b> For each day of delay beyond the agreed period not caused by the ENTITY or by force majeure, the SUPPLIER shall pay liquidated damages of {{project.ld_rate}} of the cost of the unperformed portion, deductible from any amount due.</p><p><b>9. Personnel.</b> The SUPPLIER employs and pays its personnel, complies with labor, social security and safety laws, and remains solely responsible for them; no employer-employee relationship arises between the ENTITY and the SUPPLIER\'s personnel.</p><p><b>10. Changes.</b> No change in quantity, scope, price or period is valid unless approved in writing by the ENTITY\'s authorized official in accordance with the applicable procurement rules.</p><p><b>11. Termination.</b> Either party may terminate this Agreement on the grounds and through the procedures provided by the applicable procurement law, its implementing rules and the contract documents.</p><p><b>12. Governing law and venue.</b> This Agreement is governed by the laws of the Philippines. Disputes shall first be settled amicably; failing that, through the dispute resolution provided by the applicable procurement rules, and the courts of the place of the ENTITY.</p><p><b>13. Entire agreement.</b> This Agreement and the contract documents contain the whole agreement of the parties; amendments are valid only in writing and signed by both.</p><p>IN WITNESS WHEREOF, the parties have signed this Agreement on the date and at the place first written above.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{entity.head_name}}</div><div>For the ENTITY: {{entity.head_position}}</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>For the SUPPLIER: {{signatory.position}}</div></td></tr></table><p style=\"margin-top:14px\">Signed in the presence of:</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Witness</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Witness</div></td></tr></table><h3 style=\"margin-top:20px\">ACKNOWLEDGMENT</h3><p>Republic of the Philippines )<br>________________________ ) S.S.</p><p>[Notarial acknowledgment to be completed by the notary public.]</p>','Folio','portrait',0,NULL,NULL,'entity.head_name,signatory.name,project.contract_amount',1,'layout',NULL,NULL,NULL,1,240,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(25,'contract_works','Contract agreement: infrastructure works (proforma)','contract','contract','contract','Reusable contract for minor infrastructure works. The contractor must hold the PCAB license the project calls for.','<h2 style=\"text-align:center\">CONTRACT AGREEMENT<br><span style=\"font-size:12pt\">Infrastructure Works</span></h2><p style=\"font-size:9pt;border:1px solid #999;padding:6px\"><i>Company proforma. Where the ENTITY\'s bidding documents prescribe a contract form or general and special conditions of contract, those govern; this proforma is used only as the ENTITY accepts it. Review with counsel before signing.</i></p><p>This Agreement is made on {{project.contract_date}} at {{entity.city}}, {{entity.province}}, by and between:</p><p><b>{{entity.name}}</b>, a government entity with office at {{entity.address}}, represented by <b>{{entity.head_name}}</b>, {{entity.head_position}} (the \"ENTITY\"); and</p><p><b>{{company.name}}</b>, {{company.reg_no}}, with business address at {{company.address}}, TIN {{company.tin}}, represented by <b>{{signatory.name}}</b>, {{signatory.position}} (the \"SUPPLIER\");</p><p><b>WHEREAS</b>, the ENTITY procured <b>{{project.title}}</b> ({{project.reference_no}}) through {{project.mode}} under {{project.regime}}, funded by {{project.funding_source}};</p><p><b>WHEREAS</b>, the ENTITY awarded the contract to the SUPPLIER by Notice of Award {{project.noa_ref}} dated {{project.noa_date}};</p><p><b>NOW, THEREFORE</b>, the parties agree as follows:</p><p><b>1. Contract documents.</b> The following form part of this Agreement and are read together, in this order of precedence: this Agreement; the Notice of Award; the purchase order or notice to proceed; the bid / quotation of the SUPPLIER with its price schedule; the technical specifications or terms of reference; and the general and special conditions issued by the ENTITY, if any.</p><p><b>2. Scope.</b> The SUPPLIER shall carry out and complete the works as listed below:</p>{{lines.contract_table}}<p><b>3. Contract price.</b> The contract price is <b>{{project.contract_amount}}</b> ({{project.contract_amount_words}}), inclusive of all applicable taxes, duties, delivery and other charges. The ENTITY shall withhold the taxes required by law and issue BIR Form 2307 for them.</p><p><b>4. Period and place.</b> The works at {{project.delivery_site}} shall start upon the notice to proceed dated {{project.ntp_date}} and be completed within {{project.delivery_days}}, on or before {{project.due_date}}. Progress billings follow the accomplishment certified by the ENTITY\'s engineer.</p><p><b>5. Inspection and acceptance.</b> The ENTITY, through its inspection and acceptance committee, shall inspect the deliveries or work and issue its inspection and acceptance report. Items rejected shall be replaced or corrected by the SUPPLIER at its cost within the period the ENTITY sets.</p><p><b>6. Payment.</b> {{project.payment_terms}}. Each billing shall be supported by the sales invoice, statement of account, signed delivery receipts or accomplishment reports and the inspection and acceptance report. A retention of {{project.retention_pct}} of each payment, where applicable, shall be released after the warranty period upon the ENTITY\'s final acceptance.</p><p><b>7. Warranty.</b> The SUPPLIER warrants the goods / work against defects for {{project.warranty_months}} from acceptance and shall correct any defect reported within that period at its cost.</p><p><b>8. Liquidated damages.</b> For each day of delay beyond the agreed period not caused by the ENTITY or by force majeure, the SUPPLIER shall pay liquidated damages of {{project.ld_rate}} of the cost of the unperformed portion, deductible from any amount due.</p><p><b>9. License, securities and insurance.</b> The CONTRACTOR (the SUPPLIER) holds a valid PCAB license for the category and size of this project, posts the performance security required by the contract documents, and keeps the works and its workers insured as the contract documents require. It is liable for defects of the works as provided by law.</p><p><b>10. Changes.</b> No change in quantity, scope, price or period is valid unless approved in writing by the ENTITY\'s authorized official in accordance with the applicable procurement rules.</p><p><b>11. Termination.</b> Either party may terminate this Agreement on the grounds and through the procedures provided by the applicable procurement law, its implementing rules and the contract documents.</p><p><b>12. Governing law and venue.</b> This Agreement is governed by the laws of the Philippines. Disputes shall first be settled amicably; failing that, through the dispute resolution provided by the applicable procurement rules, and the courts of the place of the ENTITY.</p><p><b>13. Entire agreement.</b> This Agreement and the contract documents contain the whole agreement of the parties; amendments are valid only in writing and signed by both.</p><p>IN WITNESS WHEREOF, the parties have signed this Agreement on the date and at the place first written above.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{entity.head_name}}</div><div>For the ENTITY: {{entity.head_position}}</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>For the SUPPLIER: {{signatory.position}}</div></td></tr></table><p style=\"margin-top:14px\">Signed in the presence of:</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Witness</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Witness</div></td></tr></table><h3 style=\"margin-top:20px\">ACKNOWLEDGMENT</h3><p>Republic of the Philippines )<br>________________________ ) S.S.</p><p>[Notarial acknowledgment to be completed by the notary public.]</p>','Folio','portrait',0,NULL,NULL,'entity.head_name,signatory.name,project.contract_amount',1,'layout',NULL,NULL,NULL,1,250,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(26,'subcontract','Subcontract agreement (company and subcontractor)','contract','internal','contract','Back-to-back subcontract for part of a barangay contract; the company stays responsible to the entity.','<h2 style=\"text-align:center\">SUBCONTRACT AGREEMENT</h2><p>This Agreement is made on {{date.today}} between <b>{{company.name}}</b>, represented by {{signatory.name}}, {{signatory.position}} (the \"CONTRACTOR\"), and <b>[Subcontractor]</b>, [address, TIN], represented by [name, position] (the \"SUBCONTRACTOR\").</p><p><b>1. Main contract.</b> The CONTRACTOR holds the contract for <b>{{project.title}}</b> with {{entity.name}} (NOA {{project.noa_ref}}). Subcontracting is allowed only as the main contract and the procurement rules allow, and the CONTRACTOR remains responsible to the entity for the whole contract.</p><p><b>2. Scope.</b> [Part of the work subcontracted, with quantities.]</p><p><b>3. Price and payment.</b> [Amount], paid within [days] after the entity accepts and pays the corresponding portion, less the same retention and deductions the entity applies to that portion.</p><p><b>4. Schedule and quality.</b> The SUBCONTRACTOR follows the specifications, schedule and inspection of the main contract and corrects rejected work at its cost.</p><p><b>5. Permits, licenses and personnel.</b> The SUBCONTRACTOR holds the licenses its work requires and is solely responsible for its personnel and their compliance with labor and safety laws.</p><p><b>6. Liquidated damages.</b> Delay caused by the SUBCONTRACTOR is charged to it at the rate the entity applies ({{project.ld_rate}}).</p><p><b>7. Confidentiality.</b> Prices and terms of the main contract are confidential.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>For the CONTRACTOR</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>For the SUBCONTRACTOR</div></td></tr></table>','A4','portrait',0,NULL,NULL,'signatory.name',1,'layout',NULL,NULL,NULL,1,260,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(27,'supply_agreement','Supply agreement with a supplier (back-to-back)','contract','internal','contract','Commits a supplier to the items, prices and delivery dates the company promised the entity.','<h2 style=\"text-align:center\">SUPPLY AGREEMENT</h2><p>Between <b>{{company.name}}</b> (the \"BUYER\"), represented by {{signatory.name}}, and <b>[Supplier]</b> (the \"SELLER\"), dated {{date.today}}.</p><p><b>1. Goods.</b> The SELLER supplies the following for the BUYER\'s contract {{project.no}} ({{project.title}}):</p><p>[Items, quantities and prices to the BUYER]</p><p><b>2. Delivery.</b> To [warehouse / site] on or before [date], allowing the BUYER to deliver to {{entity.name}} by {{project.due_date}}.</p><p><b>3. Quality and warranty.</b> The goods meet the specifications of the main contract; the SELLER replaces goods the entity rejects and honors a warranty of at least {{project.warranty_months}}.</p><p><b>4. Payment.</b> [Terms]. The BUYER withholds the taxes required by law.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>For the BUYER</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>For the SELLER</div></td></tr></table>','A4','portrait',0,NULL,NULL,'signatory.name',1,'layout',NULL,NULL,NULL,1,270,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(28,'po_conforme','Purchase order acceptance / conforme letter','letter','award','correspondence','Acknowledges the notice of award or purchase order and confirms the delivery commitment.','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Acceptance of Purchase Order / Notice of Award, {{project.title}}</b></p><p>Dear Sir / Madam:</p><p>We acknowledge receipt of your Notice of Award {{project.noa_ref}} dated {{project.noa_date}} and Purchase Order {{project.po_no}} for <b>{{project.contract_amount}}</b>, and confirm our acceptance (conforme) of their terms.</p><p>We will deliver to {{project.delivery_site}} within {{project.delivery_days}}, on or before {{project.due_date}}. Our contact person for this contract is {{project.pm}}.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'project.po_no',1,'layout','{\"signatories\":[{\"lead\":\"Conforme:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,280,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(29,'omnibus_sworn_statement','Omnibus sworn statement','proforma','bid','omnibus','The bidder\'s omnibus sworn statement (RA 12009 IRR), for notarization, filled from Contracting Settings and the transaction. The text is changed with Edit text; the header, footer and affiant on the Format tab.','<div>{{letterhead}}</div><div data-section=\"venue\" title=\"Venue (Republic of the Philippines, S.S.)\"><table class=\"fx-plain\" style=\"width:auto;margin:0 0 6px\"><tbody><tr><td style=\"padding:0 8px 0 0;white-space:nowrap\">REPUBLIC OF THE PHILIPPINES</td><td style=\"padding:0 8px 0 0;white-space:nowrap\">)</td><td></td></tr><tr><td style=\"padding:0 8px 0 0;white-space:nowrap\">CITY/MUNICIPALITY OF ____________________</td><td style=\"padding:0 8px 0 0;white-space:nowrap\">)</td><td>S.S.</td></tr></tbody></table></div><p style=\"text-align:center;margin:18px 0 16px;letter-spacing:.16em\"><b>OMNIBUS SWORN STATEMENT</b></p><p style=\"text-align:justify;text-indent:2.5em\">I, <b>{{signatory.name}}</b>, of legal age, {{signatory.civil_status}}, {{signatory.citizenship}}, and with residence at {{signatory.residence}}, after having been duly sworn in accordance with law, do hereby depose and state that:</p><ol style=\"text-align:justify;padding-left:2.4em;margin:10px 0 0\"><li style=\"margin-bottom:8px\">I am the sole proprietor or authorized representative of <b>{{company.bidder_upper}}</b> with office address at {{company.address}};</li><li style=\"margin-bottom:8px\">As the owner and sole proprietor or authorized representative of <b>{{company.bidder_upper}}</b>, I have full power and authority to do, execute and perform any and all acts necessary or appoint {{project.submitter}} to represent my company for the bidding of the <b>{{project.title}}</b> at {{entity.title}}, {{entity.city}}, {{entity.province}};</li><li style=\"margin-bottom:8px\"><b>{{company.bidder_upper}}</b> is not “blacklisted” or barred from bidding by the Government of the Philippines or any of its agencies, offices, corporations, or Local Government Units, foreign government/foreign or international financing institution whose blacklisting rules have been recognized by the Government Procurement Policy Board; by itself or by relation, membership, association, affiliation, or controlling interest with another blacklisted person or entity;</li><li style=\"margin-bottom:8px\">Each of the documents submitted in satisfaction of the bidding requirements is an authentic copy of the original, complete, and all statements and information provided therein are true and correct;</li><li style=\"margin-bottom:8px\"><b>{{company.bidder_upper}}</b> is authorizing the Head of the Procuring Entity or its duly authorized representative(s) to verify all the documents submitted;</li><li style=\"margin-bottom:8px\">I am not related to the Head of the Procuring Entity, members of the Bids and Awards Committee (BAC), the Technical Working Group, and the BAC Secretariat, the head of the Project Management Office or the end-user unit, and the project consultants by consanguinity or affinity up to the third civil degree;</li><li style=\"margin-bottom:8px\">It is understood that failure to faithfully disclose its relationship with the Head of the Procuring Entity, members of the BAC, the TWG, and the BAC Secretariat, the head of the PMO or the end-user unit or implementing unit, and the project consultants of the Procuring Entity, or of the procurement agent by consanguinity or affinity up to the third civil degree, as well as its submission of beneficial ownership information containing false entries shall be subject to blacklisting under Section 100 of the Implementing Rules and Regulations (IRR) of Republic Act (RA) No. 12009, without prejudice to criminal and civil liabilities under applicable laws, including their accessory penalties, if any;</li><li style=\"margin-bottom:8px\"><b>{{company.bidder_upper}}</b> complies with existing labor laws and standards; and</li><li style=\"margin-bottom:8px\"><b>{{company.bidder_upper}}</b> is aware of and has undertaken the following responsibilities as a Bidder:<div style=\"margin-top:6px\"><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">a)</span>Carefully examine all of the Bidding Documents;</p><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">b)</span>Acknowledge all conditions, local or otherwise, affecting the implementation of the Contract;</p><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">c)</span>Made an estimate of the facilities available and needed for the contract to be bid, if any; and</p><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">d)</span>Inquire or secure Supplemental Bid Bulletin(s) issued for the <b>{{project.title}}</b>.</p></div></li><li style=\"margin-bottom:8px\"><b>{{company.bidder_upper}}</b> did not give or pay directly or indirectly, any commission, amount, fee, or any form of consideration, pecuniary or otherwise, to any person or official, personnel or representative of the government in relation to any procurement project or activity.</li><li style=\"margin-bottom:8px\">In case advance payment was made or given to <b>{{company.bidder_upper}}</b>, failure to perform or deliver any of the obligations and undertakings in the contract shall be sufficient grounds to constitute criminal liability under existing laws.</li></ol><p style=\"text-align:justify;text-indent:2.5em;margin-top:14px\">IN WITNESS WHEREOF, I have hereunto set my hand this _____ day of ______________, 20_____ at {{company.notary_place}}, Philippines.</p><div>{{signatories}}</div><div data-section=\"jurat\" title=\"Jurat of the notary public\"><p style=\"text-align:justify;margin-top:22px\"><b>SUBSCRIBED AND SWORN</b> to before me this _____ day of ______________, 20_____ at <u>{{company.notary_place}}, Philippines</u>. Affiant/s is/are personally known to me and was/were identified by me through competent evidence of identity as defined in the 2004 Rules on Notarial Practice (A.M. No. 02-8-13-SC). Affiant/s exhibited to me his/her {{signatory.id_type}} photograph and signature appearing thereon, with <u>{{signatory.id_type}} No. {{signatory.id_no}}</u>.</p><p style=\"margin-top:16px\">WITNESS MY HAND AND SEAL this _____ day of ______________, 20_____.</p><p style=\"margin-top:20px;line-height:1.55\">Doc. No. __________<br>Page No. __________<br>Book No. __________<br>Series of {{date.year}}.</p></div>','Legal','portrait',0,NULL,NULL,'company.name,signatory.name',1,'layout','{\"paper\":\"Legal\",\"orientation\":\"portrait\",\"margin_top\":20,\"margin_right\":25.4,\"margin_bottom\":20,\"margin_left\":25.4,\"font\":\"CG Omega\",\"font_size\":11,\"line_height\":1.3,\"title_size\":14,\"table_size\":10,\"cell_pad\":2,\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"lh_style\":\"own\",\"lh_left\":\"none\",\"lh_right\":\"none\",\"lh_lines\":\"# Omnibus Sworn Statement\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":11,\"lh_big\":14,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":1,\"lh_rule_color\":\"#111111\",\"lh_space\":8,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\",\"footer\":\"\",\"footer_align\":\"center\",\"footer_bold\":0,\"footer_size\":8,\"footer_pos\":\"bottom\",\"sig_cols\":1,\"sig_top\":14,\"sig_space\":12,\"sig_gap\":8,\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Affiant\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,2,290,1,0,NULL,'2026-11-10 02:59:42',NULL,'2026-11-24 09:26:30'),
(30,'bid_securing_declaration','Bid securing declaration','proforma','bid','bid_security','The bidder\'s bid securing declaration (RA 12009 IRR), for notarization, filled from Contracting Settings and the transaction. The text is changed with Edit text; the header, footer and affiant on the Format tab.','<div>{{letterhead}}</div><div data-section=\"venue\" title=\"Venue (Republic of the Philippines, S.S.)\"><table class=\"fx-plain\" style=\"width:auto;margin:0 0 6px\"><tbody><tr><td style=\"padding:0 8px 0 0;white-space:nowrap\">REPUBLIC OF THE PHILIPPINES</td><td style=\"padding:0 8px 0 0;white-space:nowrap\">)</td><td></td></tr><tr><td style=\"padding:0 8px 0 0;white-space:nowrap\">CITY/MUNICIPALITY OF ____________________</td><td style=\"padding:0 8px 0 0;white-space:nowrap\">)</td><td>S.S.</td></tr></tbody></table></div><p style=\"text-align:center;margin:18px 0 2px\"><b style=\"font-size:1.15em\">BID SECURING DECLARATION</b></p><p style=\"text-align:center;margin:0 0 18px\"><b>Project Identification No.: <u>{{project.reference_no}}</u></b></p><p style=\"margin:0 0 14px\"><b><i>To: {{entity.title}}</i></b><br><b><i><span style=\"padding-left:2em\">{{entity.location}}, {{entity.province}}</span></i></b></p><p>I/We, the undersigned, declare that:</p><ol style=\"text-align:justify;padding-left:2.4em;margin:10px 0 0\"><li style=\"margin-bottom:8px\">I/We understand that, according to your conditions, bids must be supported by a Bid Security, which may be in the form of a Bid Securing Declaration;</li><li style=\"margin-bottom:8px\">I/We accept that: (a) I/we will be automatically disqualified from bidding for any procurement contract with any Procuring Entity upon receipt of your Blacklisting Order; and, (b) I/we will pay the applicable fine provided under the Guidelines on the Use of Bid Securing Declaration, within fifteen (15) days from receipt of the written demand by the Procuring Entity for the commission of acts resulting to the enforcement of the Bid Securing Declaration under Sections 52.2 (a), 63.2, 69.1 and 100, except 100.3 (c), of the IRR of Republic Act No. 12009; without prejudice to other legal action the government may undertake; and</li><li style=\"margin-bottom:8px\">I/We understand that this Bid Securing Declaration shall cease to be valid on the following circumstances:<div style=\"margin-top:6px\"><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">a)</span>Upon expiration of the bid validity period, or any extension thereof pursuant to your request;</p><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">b)</span>I am/we are declared ineligible or post-disqualified upon receipt of your notice to such effect, and (i) I/we failed to timely file a request for reconsideration or (ii) I/we filed a waiver to avail of said right;</p><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">c)</span>Upon contract award and the LCCRB is not the original offeror; or</p><p style=\"margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify\"><span style=\"display:inline-block;width:1.8em;text-indent:0\">d)</span>I am/we are declared the bidder with the Lowest Calculated and Responsive/Highest Rated and Responsive Bid and I/we have furnished the performance security and signed the Contract.</p></div></li></ol><p style=\"text-align:justify;text-indent:2.5em;margin-top:14px\">IN WITNESS WHEREOF, I/We have hereunto set my/our hand/s this _____ day of ______________, 20_____ at {{company.notary_place}}, Philippines.</p><div>{{signatories}}</div><div data-section=\"jurat\" title=\"Jurat of the notary public\"><p style=\"text-align:justify;margin-top:22px\"><b>SUBSCRIBED AND SWORN</b> to before me this _____ day of ______________, 20_____ at <u>{{company.notary_place}}, Philippines</u>. Affiant/s is/are personally known to me and was/were identified by me through competent evidence of identity as defined in the 2004 Rules on Notarial Practice (A.M. No. 02-8-13-SC). Affiant/s exhibited to me his/her  photograph and signature appearing thereon, with <u>{{signatory.id_type}} No. {{signatory.id_no}}</u>.</p><p style=\"margin-top:16px\">WITNESS MY HAND AND SEAL this _____ day of ______________, 20_____.</p><p style=\"margin-top:20px;line-height:1.55\">Doc. No. __________<br>Page No. __________<br>Book No. __________<br>Series of {{date.year}}.</p></div>','Legal','portrait',0,NULL,NULL,'company.name,signatory.name',1,'layout','{\"paper\":\"Legal\",\"orientation\":\"portrait\",\"margin_top\":20,\"margin_right\":25.4,\"margin_bottom\":20,\"margin_left\":25.4,\"font\":\"CG Omega\",\"font_size\":11,\"line_height\":1.3,\"title_size\":14,\"table_size\":10,\"cell_pad\":2,\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"lh_style\":\"own\",\"lh_left\":\"none\",\"lh_right\":\"none\",\"lh_lines\":\"# Bid Securing Declaration\\n({{project.title}})\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":11,\"lh_big\":14,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":1,\"lh_rule_color\":\"#111111\",\"lh_space\":8,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\",\"footer\":\"\",\"footer_align\":\"center\",\"footer_bold\":0,\"footer_size\":8,\"footer_pos\":\"bottom\",\"sig_cols\":1,\"sig_top\":14,\"sig_space\":12,\"sig_gap\":8,\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Affiant\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,NULL,2,300,1,0,NULL,'2026-11-10 02:59:42',NULL,'2026-11-24 09:26:30'),
(31,'bid_form','Bid form / price quotation form (prescribed by the entity)','prescribed','bid','quotation','Shell for the bid or quotation form the entity issued; the price schedule of the project is below to copy the figures.','<h2 style=\"text-align:center\">BID FORM / PRICE QUOTATION FORM</h2><div style=\"border:2px solid #b45309;padding:8px;margin:8px 0;background:#fff7ed\"><b>Prescribed form.</b> Paste here the current official text of this form, exactly as issued with the procuring entity\'s bidding documents or RFQ (or the GPPB\'s prescribed version they refer to), without changing its wording. Then fill its blanks with the details below and remove this box. The form cannot be made final until the official version it follows is stated.</div><p>[OFFICIAL TEXT OF THE FORM]</p><h3>Details for the blanks</h3><table class=\"ft\"><tbody><tr><td style=\"width:36%\">Name of bidder</td><td>{{company.name}}</td></tr><tr><td>Address</td><td>{{company.address}}</td></tr><tr><td>Authorized representative</td><td>{{signatory.name}}, {{signatory.position}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Project / reference</td><td>{{project.title}} ({{project.reference_no}})</td></tr><tr><td>Total bid</td><td>{{project.bid_amount}} ({{project.bid_amount_words}})</td></tr></tbody></table>{{lines.table}}','A4','portrait',1,'https://www.gppb.gov.ph/ (and the bidding documents of the procuring entity)',NULL,'company.name,signatory.name',1,'layout',NULL,NULL,NULL,1,310,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(32,'txn_form','Transaction form','internal','internal','txn_form','Series-numbered transaction form of the SOP: tradename, type, barangay, cheque, amounts, requestor, inspector and purpose.','<table class=\"fx fx-frame\" style=\"width:100%\"><tbody><tr><td style=\"padding:6px 10px\"><b>Series No:</b> <span class=\"fx-series\">{{txn.series}}</span></td></tr><tr><td class=\"fx-title\" style=\"text-align:center\">TRANSACTION FORM</td></tr><tr><td style=\"padding:8px 10px 10px\"><table class=\"fx-lines\" style=\"width:100%\"><tbody><tr><td class=\"lbl\">DATE:</td><td class=\"val\">{{txn.date}}</td></tr><tr><td class=\"lbl\">TRADENAME:</td><td class=\"val\">{{txn.tradename}}</td></tr><tr><td class=\"lbl\" style=\"vertical-align:middle\">TYPE:</td><td>{{txn.types}}</td></tr><tr><td class=\"lbl\">BARANGAY:</td><td class=\"val\">{{txn.barangay}}</td></tr><tr><td class=\"lbl\">CHEQUE NUMBER:</td><td class=\"val\">{{txn.cheque_no}}</td></tr><tr><td class=\"lbl\">GROSS AMOUNT:</td><td class=\"val\">{{txn.gross}}</td></tr><tr><td class=\"lbl\">WITHHOLDING TAX:</td><td class=\"val\">{{txn.wht}}</td></tr><tr><td class=\"lbl\">CHEQUE AMOUNT:</td><td class=\"val\">{{txn.cheque_amount}}</td></tr><tr data-section=\"profit\" title=\"Profit\"><td class=\"lbl\">PROFIT:</td><td class=\"val\">{{txn.profit}}</td></tr><tr><td class=\"lbl\">REQUESTOR:</td><td class=\"val\">{{txn.requestor}}</td></tr><tr><td class=\"lbl\">INSPECTOR:</td><td class=\"val\">{{txn.inspector}}</td></tr><tr><td class=\"lbl\">PURPOSE:</td><td class=\"val\">{{txn.purpose}}</td></tr></tbody></table></td></tr><tr><td style=\"padding:6px 10px\"><table class=\"fx-lines\" style=\"width:100%\"><tbody><tr><td class=\"lbl\" style=\"width:48%;text-align:left\">PREPARED / RECEIVED BY:</td><td class=\"val\">{{txn.prepared_by}}</td></tr></tbody></table></td></tr></tbody></table>','HalfLetter','portrait',0,NULL,NULL,'txn.series,txn.date,txn.barangay',0,'layout','{\"margin_top\":7,\"margin_right\":7,\"margin_bottom\":7,\"margin_left\":7,\"line_height\":1.25,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":12.5,\"lh_style\":\"none\",\"signatories\":[]}','{\"paper\":\"HalfLetter\",\"orientation\":\"portrait\",\"width_mm\":\"\",\"height_mm\":\"\",\"offset_x\":0,\"offset_y\":0,\"font\":\"Arial\",\"font_size\":9.5,\"fields\":[{\"key\":\"txn.series\",\"text\":\"\",\"x\":42,\"y\":5,\"w\":50,\"size\":12,\"bold\":1,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.date\",\"text\":\"\",\"x\":43,\"y\":23,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.tradename\",\"text\":\"\",\"x\":43,\"y\":29.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.mark_cash_out\",\"text\":\"\",\"x\":45.5,\"y\":35,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.mark_kaliwaan\",\"text\":\"\",\"x\":45.5,\"y\":42,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.mark_purchases\",\"text\":\"\",\"x\":45.5,\"y\":49,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.mark_construction\",\"text\":\"\",\"x\":45.5,\"y\":56,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.barangay\",\"text\":\"\",\"x\":44,\"y\":64,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.cheque_no\",\"text\":\"\",\"x\":44,\"y\":69.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.gross\",\"text\":\"\",\"x\":44,\"y\":75,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.wht\",\"text\":\"\",\"x\":44,\"y\":80.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.cheque_amount\",\"text\":\"\",\"x\":44,\"y\":86,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.profit\",\"text\":\"\",\"x\":44,\"y\":100,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.requestor\",\"text\":\"\",\"x\":44,\"y\":122,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.inspector\",\"text\":\"\",\"x\":44,\"y\":127.5,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.purpose\",\"text\":\"\",\"x\":44,\"y\":133,\"w\":52,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0},{\"key\":\"txn.prepared_by\",\"text\":\"\",\"x\":46,\"y\":148,\"w\":48,\"size\":0,\"bold\":0,\"align\":\"left\",\"upper\":0}],\"tables\":[]}',NULL,1,320,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(33,'purchase_request','Purchase request (PR)','proforma','bid','pr','Purchase request of the barangay, with the estimated unit costs, prepared by the company for the requisitioner and the Punong Barangay.','<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"2\" class=\"fx-title\" style=\"text-align:center;padding:12px\">PURCHASE REQUEST</td></tr><tr><td style=\"width:52%\">Barangay: <b>{{entity.short}}</b><br>City/Municipality: {{entity.city}}</td><td>P.R. No. {{pr.no}}<br>Date: {{pr.date}}</td></tr><tr><td colspan=\"2\" style=\"text-align:center;font-weight:bold\">REQUISITION</td></tr><tr><td colspan=\"2\" class=\"fx-slot\">{{pr.items}}</td></tr><tr><td colspan=\"2\"><b>Purpose : {{project.purpose}}</b></td></tr><tr><td style=\"height:140px;vertical-align:top\">Requested by:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{project.requestor}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Requisitioner</div></div><div class=\"fx-dateline\">Date</div></td><td style=\"vertical-align:top\">Approved by:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.head_name}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Punong Barangay</div></div><div class=\"fx-dateline\">Date</div></td></tr></tbody></table>','A4','portrait',0,NULL,NULL,'entity.name,pr.no',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":3,\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,1,330,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(34,'purchase_order','Purchase order (PO)','proforma','contract','po','Purchase order of the barangay to the company: mode of procurement, items, penalty clause, conforme and appropriations.','<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"2\" class=\"fx-title\" style=\"text-align:center;padding:12px\">PURCHASE ORDER</td></tr><tr><td colspan=\"2\" style=\"padding:0\"><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:50%\">Barangay: <b>{{entity.short_upper}}</b><br>Tel. No. {{entity.phone}}</td><td>City/Municipality: {{entity.city}}<br>Province: {{entity.province}}</td></tr></tbody></table></td></tr><tr><td style=\"width:52%\">Supplier: <b>{{company.name}}</b></td><td>P.O. No. {{po.no}}</td></tr><tr><td style=\"vertical-align:top\">Address: {{company.address}}<br>TIN:   {{company.tin}}</td><td>Date {{po.date}}<br>Mode of procurement<div style=\"margin-top:6px\">{{po.modes}}</div></td></tr><tr><td colspan=\"2\">Gentlemen:<br><span style=\"padding-left:28px\">Please deliver to this office the following articles subject to the terms and conditions contained herein</span></td></tr><tr><td>Place of Delivery: {{po.place}}<br>Date of Delivery: {{po.delivery_date}}</td><td>Delivery term: {{po.delivery_term}}<br>Payment term: {{po.payment_term}}</td></tr><tr><td colspan=\"2\" class=\"fx-slot\">{{po.items}}</td></tr><tr><td colspan=\"2\"><b>**{{po.total_words}} Only. **</b></td></tr><tr><td colspan=\"2\" style=\"padding:6px 10px 14px\"><div data-section=\"penalty\" title=\"Penalty clause\">    In case of failure to make full delivery within the time specified above, a penalty of one-tenth (1/10) of one percent for everyday of delay shall be imposed.</div><table class=\"fx-plain\" style=\"width:100%;margin-top:14px\"><tbody><tr><td style=\"width:55%\"></td><td>Very truly yours,<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.head_name}}</div><div class=\"sg-cap\">Signature Over Printed Name<br>Punong Barangay</div></div></td></tr></tbody></table></td></tr><tr><td style=\"vertical-align:top;height:150px\">Conforme:<div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{company.name_upper}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Supplier</div></div><div class=\"fx-dateline\">Date</div></td><td style=\"vertical-align:top\" data-section=\"appropriations\" title=\"Existence of available appropriations\">Existence of Available Appropriations of<div style=\"margin:6px 0\">( ____________________________________ )</div><div>(amount in words) ( figure )</div><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.appropriations_chair}}</div><div class=\"sg-cap\">Signature over Printed Name<br>Chairman, Committee on Appropriations</div></div><div>Date:</div></td></tr></tbody></table>','A4','portrait',0,NULL,NULL,'entity.name,po.no',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":9,\"title_size\":13,\"blank_rows\":2,\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,1,340,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(35,'inspection_acceptance_report','Inspection and acceptance report (IAR)','proforma','delivery','iar','Inspection and acceptance report of the barangay for the items delivered: inspection by the inspector, acceptance by the custodian.','<div class=\"fx-title\" style=\"text-align:center;margin-bottom:8px\">INSPECTION AND ACCEPTANCE REPORT</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:55%\">Entity Name: <b>{{entity.name}}</b></td><td>Fund Cluster: {{project.fund}}</td></tr><tr><td>Supplier: <b>{{company.name}}</b><br>PO No./Date: {{po.no}} / {{po.date}}</td><td><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:55%;padding:0\">IAR No.: {{iar.no}}<br>Date: {{iar.date}}</td><td style=\"padding:0\">RIS No.: {{ris.no}}<br>Date: {{ris.date}}</td></tr><tr><td colspan=\"2\" style=\"padding:0\">Invoice No.: {{iar.invoice_no}}<br>Date: {{iar.invoice_date}}</td></tr></tbody></table></td></tr><tr><td colspan=\"2\" class=\"fx-slot\">{{iar.items}}</td></tr><tr><td style=\"text-align:center;font-weight:bold\">INSPECTION</td><td style=\"text-align:center;font-weight:bold\">ACCEPTANCE</td></tr><tr><td style=\"vertical-align:top;height:170px\">Date Inspected: {{iar.date}}<p style=\"margin-top:10px\"><span class=\"fx-chk is-on\"></span> Inspected, verified and found in order as to quantity and specifications</p><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{project.inspector}}</div><div class=\"sg-cap\">Inspection Officer / Inspection Committee</div></div></td><td style=\"vertical-align:top\">Date Received: {{iar.date}}<p style=\"margin-top:10px\"><span class=\"fx-chk is-on\"></span> Complete<br><span class=\"fx-chk\"></span> Partial (pls. specify quantity)</p><div class=\"fx-sig\" style=\"text-align:center\"><div class=\"sg-name\">{{entity.treasurer}}</div><div class=\"sg-cap\">Supply and/or Property Custodian</div></div></td></tr></tbody></table>','A4','portrait',0,NULL,NULL,'entity.name,iar.no',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":3,\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,2,350,1,0,NULL,'2026-11-10 02:59:42',NULL,'2026-11-21 06:39:41'),
(36,'requisition_issue_slip','Requisition and issue slip (RIS)','proforma','delivery','ris','Requisition and issue slip of the barangay: requisition, issuance, and the four signatures.','<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"6\" class=\"fx-title\" style=\"text-align:center;padding:12px\">REQUISITION AND ISSUE SLIP</td></tr><tr><td style=\"width:12%\">Barangay:<br>Tel No.:</td><td style=\"width:24%\"><b>{{entity.short_upper}}</b><br>{{entity.phone}}</td><td style=\"width:20%\">City/Municipality:<br>Province:</td><td style=\"width:20%\">{{entity.city}}<br>{{entity.province}}</td><td style=\"width:9%\">RIS No.<br>Date:</td><td>{{ris.no}}<br>{{ris.date}}</td></tr><tr><td colspan=\"6\" class=\"fx-slot\">{{ris.items}}</td></tr><tr><td colspan=\"6\"><b>Purpose : {{project.purpose}}</b></td></tr><tr><td colspan=\"6\" style=\"padding:0\"><table class=\"fx fx-inner\" style=\"width:100%\"><tbody><tr><td style=\"width:15%;vertical-align:bottom;line-height:1.9\">Signature<br>Printed Name<br>Designation<br>Date</td><td style=\"vertical-align:top;height:110px\">Requested by:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{project.requestor}}</div><div style=\"text-align:center\">Requisitioner</div></td><td style=\"vertical-align:top;height:110px\">Approved for Issuance:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{entity.head_name}}</div><div style=\"text-align:center\">Punong Barangay</div></td><td style=\"vertical-align:top;height:110px\">Received by:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{project.requestor}}</div><div style=\"text-align:center\">Requisitioner</div></td><td style=\"vertical-align:top;height:110px\">Issued by:<div style=\"margin-top:34px;border-bottom:1px solid #000;width:80%;margin-left:auto;margin-right:auto\"></div><div style=\"text-align:center;font-weight:bold;text-decoration:underline\">{{entity.treasurer}}</div><div style=\"text-align:center\">Barangay Treasurer</div></td></tr></tbody></table></td></tr></tbody></table>','A4','portrait',0,NULL,NULL,'entity.name,ris.no',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":4,\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,1,360,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(37,'request_for_quotation','Request for quotation (canvass form)','proforma','bid','canvass','The canvass form given to each supplier: the letterhead of the BAC with the seal, the general conditions, the items with blank prices for the supplier to fill in and sign.','<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:12px 0 8px\">REQUEST FOR QUOTATION</div><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:56%\"></td><td>DATE: <u>{{rfq.date}}</u><br>QUOTATION NO.: <u>{{pr.no}}</u></td></tr></tbody></table><p style=\"margin:12px 0 0;text-align:justify\">Please quote your lowest price on the item/s listed below, subject to the General Conditions stated, stating the shortest time of delivery and submit your quotation duly signed by your representative not later than ____________________, __________ thru email: {{entity.email}} or personally at The Secretariat, Bids and Awards Committee, {{entity.short}} Barangay Hall, {{entity.short}}, {{entity.city}}.</p><div>{{signatories}}</div><div data-section=\"conditions\" title=\"General conditions\"><p style=\"margin:10px 0 2px\">GENERAL CONDITIONS:</p><ol style=\"margin:0 0 6px;padding-left:2em\"><li>All entries must be handwritten / typewritten legibly.</li><li>Approved Budget of the Contract (ABC) is <b>PHP {{project.abc_plain}}</b></li><li>Delivery period is within {{rfq.delivery_words}}.</li><li>Warranty shall be for a period of six (6) months for supplies and materials, one (1) year for equipment, from date of acceptance by the Procuring Entity.</li><li>Price shall be inclusive of VAT.</li><li>Please submit the following documents:<ol type=\"a\" style=\"margin:0;padding-left:2.6em\"><li>PhilGeps Registration Number</li><li>DTI/SEC Registration</li><li>Mayor\'s Permit</li><li>BIR Form No. 2303</li><li>Tax Clearance, if available</li></ol></li></ol></div>{{rfq.items}}<p style=\"margin:6px 0 0\">After having carefully read and accepted your General Conditions, I/We quote you on the item at prices noted above.</p><table class=\"fx-plain\" style=\"width:100%;margin-top:28px\"><tbody><tr><td style=\"width:56%\"></td><td><div style=\"border-top:1px solid #000;text-align:center\">Printed Name / Signature</div></td></tr><tr><td style=\"padding-top:28px\"><div style=\"border-top:1px solid #000;width:88%\">NAME OF ESTABLISHMENT</div></td><td style=\"padding-top:28px\"><div style=\"border-top:1px solid #000\">DATE</div></td></tr></tbody></table>','A4','portrait',0,NULL,NULL,'entity.name',0,'layout','{\"margin_top\":10,\"margin_right\":15,\"margin_bottom\":10,\"margin_left\":15,\"line_height\":1.25,\"cell_pad\":2,\"font_size\":10,\"table_size\":9.5,\"title_size\":13,\"blank_rows\":6,\"sig_top\":6,\"sig_space\":8,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"half\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"own\",\"lh_left\":\"seal\",\"lh_right\":\"pic_a\",\"lh_lines\":\"**REPUBLIC OF THE PHILIPPINES**\\nProvince of {{entity.province}}\\n{{entity.lgu_line}}\\n{{entity.title}}\\n**BIDS AND AWARD COMMITTEE**\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":10.5,\"lh_big\":15,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":0,\"lh_rule_color\":\"#111111\",\"lh_space\":4,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\"}',NULL,NULL,2,370,1,0,NULL,'2026-11-10 02:59:42',NULL,'2026-11-21 06:39:41'),
(38,'abstract_of_canvass','Abstract of bids as quoted (abstract of canvass)','proforma','bid','abstract','The quotations of the suppliers canvassed side by side (total, validity, brand, remarks), signed by the BAC and approved by the Punong Barangay.','<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:58%\"></td><td>P.R No. : {{pr.no}}<br>Name of Project: {{project.title}}<br>Location of the Project: {{entity.location}}</td></tr></tbody></table><div class=\"fx-title\" style=\"text-align:center;margin:18px 0 4px;text-decoration:underline\">ABSTRACT OF BIDS AS QUOTED</div><p style=\"text-align:right\">( {{abstract.date}} )</p><p><b>Project Name: {{project.title}}<br>Project Location: {{entity.name}}, {{entity.city}}<br>Implementing Office: {{project.end_user}}</b></p><p style=\"margin:12px 0 2px\"><b>Approved Budget for the Contract: {{project.abc}}</b></p>{{abstract.table}}<div style=\"margin-top:34px\">{{entity.bac_signatures}}</div><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":10,\"table_size\":9,\"title_size\":13,\"lh_style\":\"none\",\"sig_top\":8,\"signatories\":[{\"lead\":\"Approved by:\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"PUNONG BARANGAY\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,380,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(39,'disbursement_voucher','Disbursement voucher (DV)','proforma','billing','dv','Disbursement voucher of the barangay for the payment to the company: particulars, taxes withheld, net amount in words, supporting papers, boxes A to E.','<table class=\"fx\" style=\"width:100%\"><tbody><tr><td colspan=\"2\" class=\"fx-title\" style=\"text-align:center;padding:10px\">DISBURSEMENT VOUCHER</td><td style=\"width:22%;vertical-align:bottom\">DV No. {{dv.no}}</td></tr><tr><td style=\"width:46%\">Barangay: <b>{{entity.short}}</b></td><td>City/Municipality: {{entity.city}}</td><td>Date: {{dv.date}}</td></tr><tr><td>Payee: <b>{{company.name}}</b></td><td>Province: {{entity.province}}</td><td>Fund: {{dv.fund}}</td></tr><tr><td>Address: {{company.address}}</td><td>TIN: {{company.tin}}</td><td></td></tr><tr><td colspan=\"3\" style=\"text-align:center;font-weight:bold\">PARTICULARS</td></tr><tr><td colspan=\"3\" style=\"padding:10px 14px\"><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:70%\">To Withdraw Payment for the <b>{{dv.particulars}}</b><br>per attached supporting documents in the amount of ------------</td><td style=\"text-align:right;font-size:12pt;font-weight:bold;vertical-align:bottom\">{{dv.gross}}</td></tr><tr data-section=\"taxes\" title=\"Taxes withheld\"><td style=\"padding-top:16px\">{{dv.taxes}}</td><td style=\"text-align:right;font-size:12pt;font-weight:bold;vertical-align:bottom\">{{dv.net}}</td></tr><tr><td colspan=\"2\" style=\"padding:18px 0 0 18px\">Amount in words:<br><b>{{dv.net_words_upper}}</b></td></tr><tr data-section=\"papers\" title=\"Supporting papers attached\"><td colspan=\"2\" style=\"padding:18px 0 0 18px\">Supporting Papers Attached:{{dv.papers}}</td></tr><tr><td></td><td style=\"text-align:right;font-size:12pt\"><b>TOTAL:   {{dv.net}}</b></td></tr></tbody></table></td></tr><tr><td colspan=\"3\" style=\"padding:0\"><table class=\"fx fx-inner\" style=\"width:100%\"><tbody><tr><td style=\"width:34%;vertical-align:top\"><span class=\"fx-tag\">A</span> <b>Certified:</b><br>Existence of available appropriations for the charges/expenses indicated above<div style=\"margin-top:26px\">Signature:<br>Printed Name: <b><u>{{entity.appropriations_chair_upper}}</u></b><br>Position: Chairman, Committee on Appropriations<br><b>Date:</b></div></td><td style=\"width:33%;vertical-align:top\"><span class=\"fx-tag\">B</span> <b>Certified:</b><br>Funds (Cash) Available:<br><br><div style=\"margin-top:26px\">Signature:<br>Printed Name: <b><u>{{entity.treasurer_upper}}</u></b><br>Position: Barangay Treasurer<br><b>Date:</b></div></td><td style=\"vertical-align:top\"><span class=\"fx-tag\">C</span> <b>Certified:</b><br>As to validity, propriety, and legality of claim<br>Approved: FOR PAYMENT<div style=\"margin-top:26px\">Signature:<br>Printed Name: <b><u>{{entity.head_name_upper}}</u></b><br>Position: Barangay Captain<br><b>Date:</b></div></td></tr></tbody></table></td></tr><tr><td colspan=\"3\" style=\"vertical-align:top;height:110px\"><span class=\"fx-tag\">D</span> <b>Received Payment:</b><table class=\"fx-plain\" style=\"width:100%;margin-top:16px\"><tbody><tr><td style=\"width:50%;padding-left:40px\"><b><u>{{company.name_upper}}</u></b><br>Signature Over Printed Name</td><td>Check No. <u>{{dv.check_no}}</u><br>Bank Name: <u>{{dv.bank}}</u><br>OR Number: <u>{{dv.or_no}}</u></td><td style=\"vertical-align:middle\">Date: __________</td></tr><tr><td style=\"padding-top:10px\">Date: __________</td><td></td><td></td></tr></tbody></table></td></tr><tr><td colspan=\"3\" style=\"padding:0\" data-section=\"entries\" title=\"E. Accounting entries\"><table class=\"fx fx-inner\" style=\"width:100%\"><tbody><tr><td colspan=\"4\"><b>E. Accounting Entries:</b></td></tr><tr><th style=\"width:36%\">Account</th><th style=\"width:22%\">Account Code</th><th style=\"width:21%\">Debit</th><th>Credit</th></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td> </td><td></td><td></td><td></td></tr><tr><td style=\"vertical-align:top;height:150px\"></td><td colspan=\"3\" style=\"vertical-align:top\">Prepared By:<table class=\"fx-plain\" style=\"width:100%;margin-top:26px\"><tbody><tr><td style=\"width:62%;text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>{{entity.bookkeeper}}<br>Barangay Bookkeeper</td><td style=\"text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>Date</td></tr></tbody></table><div style=\"margin-top:12px\">Approved By:</div><table class=\"fx-plain\" style=\"width:100%;margin-top:22px\"><tbody><tr><td style=\"width:62%;text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>{{entity.city_accountant}}<br>City/Municipal Accountant</td><td style=\"text-align:center\"><div style=\"border-top:1px solid #000;width:70%;margin:0 auto\"></div>Date</td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table>','A4','portrait',0,NULL,NULL,'entity.name,dv.gross',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":8.5,\"title_size\":13,\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,1,390,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(40,'document_transmittal','Transmittal of documents (SOP)','letter','billing','transmittal','Transmittal of the papers released to the barangay (delivered by the sales representative or picked up at the office); the signed copy must come back.','<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">TRANSMITTAL</div><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:60%\">To: <b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</td><td style=\"vertical-align:top\">Transmittal No.: <b>{{transmittal.no}}</b><br>Date: {{transmittal.date}}<br>Transaction: {{project.txn_form_no}}<br>P.O. No.: {{po.no}}</td></tr></tbody></table><p style=\"margin-top:12px\">We are transmitting herewith the following documents for <b>{{project.title}}</b>:</p>{{sop.papers_table}}<p>Kindly acknowledge receipt by signing below and returning a copy of this transmittal.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name,transmittal.no',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":8,\"signatories\":[{\"lead\":\"Released by:\",\"name\":\"{{transmittal.released_by}}\",\"pos\":\"{{company.name}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Received by:\",\"name\":\"\",\"pos\":\"Signature over Printed Name \\/ Date\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":1,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\"}',NULL,NULL,1,400,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(41,'bidding_form','Bidding form (details of the bidding)','internal','internal','bidding_form','The details of a bidding given by the sales representative: project, budget, schedule, specifications and submission requirements.','<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">BIDDING FORM</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Series / project no.</td><td>{{project.no}}   {{project.txn_form_no}}</td></tr><tr><td>Procuring entity</td><td><b>{{entity.name}}</b>, {{entity.city}}, {{entity.province}}</td></tr><tr><td>Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Pre-bid conference</td><td>{{project.prebid}}</td></tr><tr><td>Bid deadline / opening</td><td>{{project.bid_deadline}}</td></tr><tr><td>Requestor / end-user</td><td>{{project.requestor}} {{project.end_user}}</td></tr><tr><td>Inspector</td><td>{{project.inspector}}</td></tr><tr><td>Submission requirements</td><td>{{entity.requirement_notes}}</td></tr><tr><td>Specifications</td><td>{{project.specs}}</td></tr><tr><td>Sales representative</td><td>{{project.sales_rep}}</td></tr></tbody></table>{{lines.table}}','A4','portrait',0,NULL,NULL,'project.title,entity.name',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"signatories\":[],\"lh_style\":\"company\"}',NULL,NULL,1,410,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(42,'invitation_to_bid','Invitation to bid (ITB)','proforma','bid','itb','Invitation to bid in the name of the Bids and Awards Committee of the barangay.','<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:12px 0\">INVITATION TO BID</div><p style=\"text-align:center\"><b>{{project.title}}</b><br>{{project.reference_no}}</p><ol><li>The {{entity.name}}, through its approved budget, intends to apply the sum of <b>{{project.abc_words}} ({{project.abc}})</b> being the Approved Budget for the Contract (ABC) to payments under the contract for {{project.title}}. Bids received in excess of the ABC shall be automatically rejected at bid opening.</li><li>The {{entity.name}} now invites bids for the above procurement project. Delivery of the goods is required within {{project.delivery_days}}. Bidders should have completed a contract similar to the project.</li><li>Bidding will be conducted through open competitive bidding procedures using a non-discretionary \"pass/fail\" criterion as specified in the applicable procurement law and its implementing rules.</li><li>A pre-bid conference shall be held on {{project.prebid}} at {{entity.address}}.</li><li>Bids must be duly received by the BAC Secretariat at {{entity.address}} on or before {{project.bid_deadline}}. Late bids shall not be accepted.</li><li>The {{entity.name}} reserves the right to reject any and all bids, declare a failure of bidding, or not award the contract at any time prior to contract award, without thereby incurring any liability to the affected bidder or bidders.</li></ol><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name,project.title,project.abc',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"half\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}',NULL,NULL,1,420,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(43,'letter_to_coa','Letter to COA','letter','bid','coa_letter','Letter of the BAC informing the COA auditor of the bidding schedule and inviting a representative as observer.','<div>{{letterhead}}</div><p style=\"text-align:right\">{{date.today}}</p><p><b>The Audit Team Leader</b><br>Commission on Audit<br>{{entity.city}}, {{entity.province}}</p><p><b>Subject: Invitation to observe the bidding for {{project.title}}</b></p><p>Sir/Madam:</p><p>The Bids and Awards Committee of {{entity.name}} respectfully informs your office of the procurement of <b>{{project.title}}</b> ({{project.reference_no}}) with an Approved Budget for the Contract of {{project.abc}}.</p><p>The pre-bid conference is scheduled on {{project.prebid}} and the opening of bids on {{project.bid_deadline}}, at {{entity.address}}. We would be glad to have a representative of your office attend as observer.</p><p>Thank you.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":6,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}',NULL,NULL,1,430,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(44,'approved_budget_contract','Approved budget for the contract (ABC)','proforma','bid','abc','Certification of the approved budget for the contract, with its breakdown (asked by the Cebu City offices).','<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:12px 0\">APPROVED BUDGET FOR THE CONTRACT</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference</td><td>{{project.reference_no}}</td></tr><tr><td>Source of funds</td><td>{{project.funding_source}}</td></tr><tr><td>Approved budget</td><td><b>{{project.abc}}</b> ({{project.abc_words}})</td></tr></tbody></table>{{pr.items}}<p>This is to certify that the above amount is the approved budget for the contract of the project.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name,project.abc',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.treasurer_upper}}\",\"pos\":\"Barangay Treasurer\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"Punong Barangay\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}',NULL,NULL,1,440,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(45,'special_power_of_attorney','Special power of attorney (SPA)','contract','bid','spa','Special power of attorney of the proprietor appointing the representative for the pre-bid conference and the bidding (for notarization).','<div class=\"fx-title\" style=\"text-align:center;margin:6px 0 14px\">SPECIAL POWER OF ATTORNEY</div><p><b>KNOW ALL MEN BY THESE PRESENTS:</b></p><p>I, <b>{{signatory.name}}</b>, of legal age, Filipino, {{signatory.position}} of <b>{{company.name}}</b>, with business address at {{company.address}}, do hereby name, constitute and appoint <b>{{project.submitter}}</b>, of legal age, as my true and lawful attorney-in-fact, for me and in my name, place and stead, to do and perform the following acts:</p><ol><li>To attend the pre-bid conference and the opening of bids of <b>{{project.title}}</b> ({{project.reference_no}}) of the {{entity.name}};</li><li>To submit, sign and receive all documents relative to the said bidding, including the bid, clarifications and notices;</li><li>To do all acts necessary and incidental to the foregoing.</li></ol><p>HEREBY GIVING AND GRANTING unto my said attorney-in-fact full power and authority to do and perform the acts above, and hereby ratifying all that my said attorney-in-fact shall lawfully do by virtue hereof.</p><p>IN WITNESS WHEREOF, I have hereunto set my hand this ____ day of __________ at __________.</p><div>{{signatories}}</div><p style=\"margin-top:22px\"><b>ACKNOWLEDGMENT</b></p><p>[Notarial acknowledgment]</p>','A4','portrait',0,NULL,NULL,'signatory.name,project.submitter',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"lh_style\":\"none\",\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Principal\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"{{project.submitter}}\",\"pos\":\"Attorney-in-fact\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}]}',NULL,NULL,1,450,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(46,'statement_ongoing_contracts','Statement of all ongoing government and private contracts','proforma','bid','slcc','Ongoing government and private contracts, incl. those awarded but not started (step 8 of the bidding): the company\'s other awarded contracts not closed fill the government part; private ones are typed on the form.','<p style=\"margin:0;line-height:1.3\"><i>Procuring Entity:</i> <b>{{entity.title}}</b><br><i>Name of the Project:</i> <b>{{project.title}}</b><br><i>Location of the Project:</i> <b>{{project.location}}</b></p><p style=\"margin:8px 0 6px\"><span class=\"fx-hl\" style=\"font-size:14pt;font-weight:bold\">Statement of all Ongoing Government &amp; Private Contracts including contracts awarded but not yet started</span></p><table class=\"fx-plain fx-kv\" style=\"margin:4px 0 6px\"><tbody><tr><td class=\"k\">Business Name</td><td>: <u>{{company.name}}</u></td></tr><tr><td class=\"k\">Business Address</td><td>: <u>{{company.address}}</u></td></tr></tbody></table><div style=\"margin-top:6px\">{{contracts.ongoing_table}}</div><p style=\"margin:6px 0 0\">Note: This statement shall be supported with:</p><ol style=\"margin:0;padding-left:2.4em\"><li>Purchase Order / Notice to Proceed</li><li>Notice of Award</li></ol><table class=\"fx-plain fx-kv\" style=\"margin-top:22px\"><tbody><tr><td class=\"k\" style=\"width:110px\">Submitted by</td><td>: <b><u>{{signatory.name}}</u></b></td></tr><tr><td></td><td style=\"padding-left:14px;font-size:.92em\">(Printed Name &amp; Signature)</td></tr><tr><td class=\"k\">Designation</td><td>: <u>{{signatory.position}}</u></td></tr><tr><td class=\"k\">Date</td><td>: {{date.today}}</td></tr></tbody></table>','Legal','landscape',0,NULL,NULL,'company.name,project.title',0,'layout','{\"margin_top\":15,\"margin_right\":18,\"margin_bottom\":15,\"margin_left\":18,\"line_height\":1.25,\"cell_pad\":3,\"font_size\":10,\"table_size\":9.5,\"title_size\":14,\"paper\":\"Legal\",\"orientation\":\"landscape\",\"font\":\"CG Omega\",\"date_style\":\"mdy\",\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,1,460,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(47,'statement_similar_contracts','Statement of the single largest completed contract similar to the contract to be bid (SLCC)','proforma','bid','slcc','Statement identifying the bidder\'s single largest completed contract similar to the contract to be bid (step 8 of the bidding): the largest closed contract of the company of the same category.','<p style=\"margin:0;line-height:1.3\"><i>Procuring Entity:</i> <b>{{entity.title}}</b><br><i>Name of the Project:</i> <b>{{project.title}}</b><br><i>Location of the Project:</i> <b>{{project.location}}</b></p><p style=\"margin:6px 0 6px\"><span class=\"fx-hl\" style=\"font-size:14pt;font-weight:bold\">Statement identifying the bidder’s single largest completed contract similar to the contract to be bid</span></p><table class=\"fx-plain fx-kv\" style=\"margin:4px 0 6px\"><tbody><tr><td class=\"k\">Business Name</td><td>: <u>{{company.name}}</u></td></tr><tr><td class=\"k\">Business Address</td><td>: <u>{{company.address}}</u></td></tr></tbody></table><div style=\"margin-top:6px\">{{contracts.slcc_table}}</div><p style=\"margin:6px 0 0\">Note: This statement shall be supported with:</p><p style=\"margin:0;padding-left:2em\">1. Purchase Order     2. Sales Invoice     3. Certificate of Completion / Delivery Receipt     4. Notice of Award     5. Notice to Proceed</p><table class=\"fx-plain fx-kv\" style=\"margin-top:22px\"><tbody><tr><td class=\"k\" style=\"width:110px\">Submitted by</td><td>: <b><u>{{signatory.name}}</u></b></td></tr><tr><td></td><td style=\"padding-left:14px;font-size:.92em\">(Printed Name &amp; Signature)</td></tr><tr><td class=\"k\">Designation</td><td>: <u>{{signatory.position}}</u></td></tr><tr><td class=\"k\">Date</td><td>: {{date.today}}</td></tr></tbody></table>','Folio','landscape',0,NULL,NULL,'company.name,project.title',0,'layout','{\"margin_top\":15,\"margin_right\":18,\"margin_bottom\":15,\"margin_left\":18,\"line_height\":1.25,\"cell_pad\":3,\"font_size\":10,\"table_size\":9.5,\"title_size\":14,\"paper\":\"Folio\",\"orientation\":\"landscape\",\"font\":\"CG Omega\",\"date_style\":\"mdy\",\"lh_style\":\"none\",\"signatories\":[]}',NULL,NULL,1,470,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(48,'supplier_profile','Supplier profile','proforma','bid','company_profile','The supplier profile asked by the barangay (step 8 of the bidding): the firm, its general information, the person managing its affairs and the authorized liaison officer (Contracting Settings).','<div>{{letterhead}}</div><p style=\"text-align:center;margin:14px 0 28px\"><span style=\"font-size:20pt;font-weight:bold;text-decoration:underline\">SUPPLIER</span></p><p style=\"margin:0 0 6px\"><b><u>Profile</u></b></p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Date</td><td>: {{date.today}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Name of Firm/Company</td><td>: <b>{{company.name_upper}}</b></td></tr><tr><td class=\"k\" style=\"width:34%\">Tax Account Number</td><td>: {{company.tin}}</td></tr></tbody></table><p style=\"margin:18px 0 6px\"><b><u>General Information</u></b></p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Address</td><td>: {{company.address}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Telephone Number</td><td>: {{company.phone}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Email Address</td><td>: {{company.email}}</td></tr></tbody></table><p style=\"margin:18px 0 6px\"><b><u>Legal Aspect</u></b></p><p style=\"margin:0 0 6px\">Persons Managing affairs of the Firm</p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Name</td><td>: {{company.manager_upper}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Designation</td><td>: {{company.manager_position}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Telephone</td><td>: {{company.manager_phone}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Cellphone No.</td><td>: {{company.manager_mobile}}</td></tr></tbody></table><p style=\"margin:18px 0 6px\">Authorized Liaison Officer</p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Name</td><td>: {{company.liaison_upper}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Designation</td><td>: {{company.liaison_position}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Telephone</td><td>: {{company.liaison_phone}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Cellphone No.</td><td>: {{company.liaison_mobile}}</td></tr></tbody></table>','Legal','portrait',0,NULL,NULL,'company.name,company.tin',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"signatories\":[],\"lh_style\":\"own\",\"lh_left\":\"none\",\"lh_right\":\"none\",\"lh_lines\":\"Republic of the Philippines\\nProvince of {{entity.province}}\\n{{entity.lgu_line}}\\n**{{entity.short_upper}} Barangay Hall**\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":11,\"lh_big\":16,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":0,\"lh_rule_color\":\"#111111\",\"lh_space\":8,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}',NULL,NULL,1,480,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(49,'letter_of_intent','Letter of intent (manifestation of intent to participate)','letter','bid','letter_intent','Manifestation of intent to participate in the public bidding (step 8 of the bidding), on the company letterhead.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:22px 0 26px\"><span style=\"font-size:16pt;font-weight:bold\">Manifestation of Intent to Participate</span></p><p><b>{{date.today}}</b></p><p style=\"margin-top:18px\"><b>OFFICE OF THE CHAIRMAN</b><br>Bids and Awards Committee<br><b>{{entity.title}}</b><br>{{entity.city}}, {{entity.province}}</p><p>Dear Sir/Madam:</p><p style=\"text-align:justify\">This refers to the procurement project entitled <b>{{project.title}}.</b></p><p style=\"text-align:justify\">In this regard, <b>{{company.name}}</b>, with business address at <b>{{company.address}}</b>, hereby formally manifests its intent to participate in the public bidding for the above-mentioned project, in accordance with {{project.law_text}} and its Implementing Rules and Regulations (IRR).</p><p style=\"text-align:justify\">This manifestation is submitted in compliance with the requirements of the Bidding Documents issued by your office. Should our participation be accepted, we commit to comply with all eligibility requirements, submission of bidding documents, and other conditions set forth by the Bids and Awards Committee (BAC) within the prescribed timelines.</p><p style=\"text-align:justify\">We trust that this manifestation satisfies your requirement for expression of interest. We look forward to participating in the bidding process.</p><p style=\"margin-top:18px\">Thank you for your consideration.</p><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":12,\"lh_space\":4,\"signatories\":[{\"lead\":\"Respectfully yours,\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}',NULL,NULL,1,490,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(50,'technical_specifications','Technical specifications (Section VII) with the statement of compliance','proforma','bid','technical_proposal','Section VII - Technical specifications of the bid (step 8 of the bidding): each item with its specifications, one a line, and the statement of compliance. A line in capitals or ending with \":\" prints bold; **text** is bold too.','<p style=\"text-align:center;margin:0 0 20px\"><span style=\"font-size:16pt;font-weight:bold;text-decoration:underline\">SECTION VII-TECHNICAL SPECIFICATIONS</span></p><p><b>Date:</b> {{date.today}}</p><p>To: {{entity.short}} Barangay Hall, {{entity.city}}, {{entity.province}}<br>Address: {{entity.address}}</p><p>Gentlemen and/ or Ladies,</p><div>{{specs.items}}</div><p style=\"margin-top:10px\">We can <b><u>comply</u></b> the technical specification stated in the Bid Form.</p><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":22,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"lh_style\":\"none\",\"sig_cols\":1,\"sig_top\":16,\"sig_space\":14,\"comply_text\":\"\\\"comply\\\"\",\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Dealer\'s Signature\",\"extra\":\"**{{company.name_upper}}**\\n{{company.address}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}',NULL,NULL,1,500,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(51,'production_details','Production details (Section VI: schedule of requirements)','proforma','bid','production','Section VI - Schedule of requirements (step 8 of the bidding): the items with their specifications, the quantity, and the delivery period in weeks or months.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:8px 0 18px\"><span style=\"font-size:16pt;font-weight:bold;text-decoration:underline\">SECTION VI-SCHEDULE OF REQUIREMENTS</span></p><div>{{sched.items}}</div><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":20,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":1,\"font_size\":10,\"table_size\":9.5,\"title_size\":14,\"sig_cols\":1,\"sig_top\":14,\"sig_space\":14,\"th_bg\":\"#fff2cc\",\"signatories\":[{\"lead\":\"**{{company.name_upper}}**\\n{{company.address_upper}}\",\"name\":\"{{signatory.name}}\",\"pos\":\"Dealer\'s Signature\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"own\",\"lh_left\":\"none\",\"lh_right\":\"none\",\"lh_lines\":\"Republic of the Philippines\\nProvince of {{entity.province}}\\n{{entity.lgu_line}}\\n**{{entity.short}}** Barangay Hall\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":11,\"lh_big\":16,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":0,\"lh_rule_color\":\"#111111\",\"lh_space\":8,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}',NULL,NULL,1,510,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(52,'manpower_schedule','Manpower schedule (manpower requirements)','proforma','bid','manpower','Manpower requirements of the delivery (step 8 of the bidding), on the company letterhead.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:18px 0 30px\"><span style=\"font-size:18pt;font-weight:bold\">MANPOWER REQUIREMENTS</span></p><p style=\"text-align:justify\">In compliance with the requirements of the Bids and Awards Committee (BAC), and based on our standard delivery procedures and actual delivery operations, the following manpower requirement is hereby submitted:</p><p style=\"text-align:justify\">All goods and services shall be delivered to the designated delivery site and shall be subject to inspection upon delivery.</p><table class=\"fx\" style=\"width:100%;margin-top:22px\"><thead><tr><th style=\"width:28%\">PARTICULARS</th><th>DETAILS</th></tr></thead><tbody><tr><td><b>Project Name:</b></td><td>{{project.title}}</td></tr><tr><td style=\"vertical-align:middle\"><b>Project Location:</b></td><td>{{project.location}}</td></tr><tr><td><b>Delivery Vehicle:</b></td><td>Any available vehicle</td></tr><tr><td style=\"vertical-align:middle\"><b>Required Personnel</b></td><td>At least two (2) personnel composed of:<br>• One (1) Driver<br>• One (1) Sales Representative</td></tr></tbody></table><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'project.title',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":22,\"sig_space\":12,\"signatories\":[{\"lead\":\"Respectfully submitted by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}',NULL,NULL,1,520,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(53,'warranty_certificate','Warranty certificate (after-sales service and warranty provision)','proforma','bid','warranty_cert','After-sales service and warranty provision (step 8 of the bidding), on the company letterhead. The warranty period comes from the project (warranty in months).','<div>{{letterhead}}</div><p style=\"text-align:center;margin:10px 0 14px\"><span style=\"font-size:11.5pt;font-weight:bold\">After-Sales Service and Warranty Provision</span></p><p style=\"text-align:justify\">The Supplier shall warrant that the {{project.title}}, including all its components, accessories, and attachments, is brand new, free from defects in materials and workmanship, and compliant with the technical specifications prescribed in the Contract.</p><p style=\"margin-bottom:0\"><b>1. Warranty Period</b></p><p style=\"text-align:justify\">The warranty shall be for a minimum period of <b>{{project.warranty_words}}</b>, reckoned from the date of final acceptance by the Procuring Entity.</p><p style=\"margin-bottom:0\"><b>2. Scope of Warranty</b></p><p style=\"margin-bottom:2px\">The warranty shall cover, but not be limited to, defects or failures in the following:</p><ul style=\"margin-top:4px\"><li>Materials and workmanship of every item delivered</li><li>The performance of the goods according to the technical specifications</li><li>Components, parts, and assemblies</li><li>Electrical, mechanical, and operating systems, where applicable</li><li>All factory-installed parts, equipment, and accessories</li></ul><p style=\"text-align:justify\">The Supplier shall undertake, at its own expense, the repair or replacement of any defective parts, including the provision of labor, tools, and consumables necessary to restore the goods to their optimal operating condition.</p><p style=\"margin-bottom:0\"><b>3. After-Sales Service Obligations</b></p><p style=\"margin-bottom:0\">The Supplier shall:</p><p style=\"text-align:justify;margin-bottom:0\">a. Maintain or have access to an <b>authorized service center</b> capable of providing adequate technical support within a reasonable distance from the Procuring Entity;<br>b. Ensure the availability of <b>genuine spare parts</b> for a minimum period of <b>five (5) years</b> from delivery;<br>c. Provide <b>preventive maintenance services</b> in accordance with the manufacturer’s recommended schedule, where applicable;<br>d. Respond to service requests within <b>forty-eight (48) to seventy-two (72) hours</b> from receipt of notice;<br>e. Deploy qualified technical personnel to perform necessary inspections, diagnostics, and repairs.</p><p style=\"margin:10px 0 0\"><b>4. Exclusions from Warranty</b></p><p style=\"margin-bottom:2px\">The warranty shall not apply to defects or damages resulting from:</p><ul style=\"margin-top:4px\"><li>Misuse, negligence, or improper operation by the end-user;</li><li>Unauthorized repairs, alterations, or modifications;</li><li>Accidents, force majeure, or external causes beyond normal operating conditions;</li><li>Normal wear and tear of consumable items, unless proven to be factory-defective.</li></ul><p style=\"margin-bottom:0\"><b>5. Warranty Security</b></p><p style=\"text-align:justify\">In accordance with the applicable procurement law and its Implementing Rules and Regulations, the Supplier shall post a <b>warranty security</b> in any of the acceptable forms prescribed by law to guarantee the faithful performance of its warranty obligations.</p><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'project.title',0,'layout','{\"margin_top\":18,\"margin_right\":25.4,\"margin_bottom\":18,\"margin_left\":25.4,\"line_height\":1.22,\"cell_pad\":3,\"font_size\":10.5,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":12,\"lh_space\":4,\"signatories\":[{\"lead\":\"Sincerely yours,\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}',NULL,NULL,1,530,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(54,'notice_of_post_qualification','Notice of post-qualification','proforma','award','post_qual_notice','Notice of the BAC that the company passed the post-qualification and its bid is the lowest calculated and responsive bid (step 13 of the bidding), prepared for the BAC Chairman\'s signature.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:4px 0 22px\"><span style=\"font-size:14pt;font-weight:bold\">Notice of Post Qualification</span></p><p>{{date.today}}</p><p style=\"margin-top:18px\"><b>{{signatory.addressee}}</b><br>{{signatory.position_upper}}<br><b>{{company.name_upper}}</b><br>{{company.address}}</p><p style=\"margin-top:22px\"><b><u>ATTN.: {{signatory.addressee}}</u></b></p><p style=\"margin-top:22px\">Good day!</p><p style=\"text-align:justify;line-height:1.7\">After determining your bid as the Lowest Calculated Bid for the <b>{{project.title}}</b> for {{entity.title}}, {{entity.city}} and upon the post qualification involving the careful examination, validation and verification of the eligibility, technical and financial requirements that you have submitted for bidding. We are happy to inform you that you have successfully passed the Post Qualification and therefore, now consider your bid as the Lowest Calculated and Responsive for the said Contract.</p><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":14,\"sig_space\":10,\"sig_gap\":8,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"HON. {{entity.bac_chair_upper}}\",\"pos\":\"BAC CHAIRMAN\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":1},{\"lead\":\"Received by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"PRINTED NAME AND SIGNATURE\",\"extra\":\"\",\"align\":\"left\",\"newrow\":1,\"line\":0,\"bold\":0,\"underline\":1,\"upper\":0,\"italic\":1}],\"footer\":\"OFFICE OF THE BARANGAY\",\"footer_align\":\"center\",\"footer_bold\":1,\"footer_size\":11,\"footer_pos\":\"bottom\",\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}',NULL,NULL,1,540,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(55,'notice_of_award','Notice of award (NOA)','proforma','award','noa','Notice of award to the company (step 13 of the bidding), for the Punong Barangay\'s signature and the conforme of the company.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:4px 0 22px\"><span style=\"font-size:14pt;font-weight:bold\">NOTICE OF AWARD</span></p><p>{{date.today}}</p><p style=\"margin-top:18px\"><b>{{signatory.addressee}}</b><br>{{signatory.position_upper}}<br><b>{{company.name_upper}}</b><br>{{company.address}}</p><p style=\"margin-top:18px\">Dear {{signatory.salutation}}:</p><p style=\"text-align:justify;line-height:1.6\">We are happy to notify you that the contract for the <b>{{project.title}}</b> is hereby awarded to you as the single lowest calculated and responsive Bid at a contract price equivalent to <b>{{project.contract_price_text}}</b>.</p><p style=\"text-align:justify;line-height:1.6\">You are therefore required to provide the performance security in the form and amount stipulated in the instruction to the Bidders within ten (10) calendar days from receipt of Notice of Award. Contract signing will be done upon submission of the required performance security. Failure to provide the performance security on the said date shall constitute ground for cancellation of the award and forfeiture of the bid security.</p><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'entity.name,project.title,project.bid_amount',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":10,\"sig_gap\":8,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"HON. {{entity.head_name_upper}}\",\"pos\":\"Barangay Chairman\",\"extra\":\"{{entity.location}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Conforme:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{company.name_upper}}\",\"extra\":\"Date: {{date.today}}\",\"align\":\"left\",\"newrow\":1,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"footer\":\"OFFICE OF THE BARANGAY\",\"footer_align\":\"center\",\"footer_bold\":1,\"footer_size\":11,\"footer_pos\":\"bottom\",\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}',NULL,NULL,1,550,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(56,'notice_to_proceed','Notice to proceed (NTP)','proforma','award','ntp','Notice to proceed (step 13 of the bidding), for the Punong Barangay\'s signature and the acknowledgment of the company\'s representative.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:4px 0 22px\"><span style=\"font-size:14pt;font-weight:bold\">NOTICE TO PROCEED</span></p><p>{{date.today}}</p><p style=\"margin-top:18px\"><b>{{signatory.addressee}}</b><br>{{signatory.position_upper}}<br><b>{{company.name_upper}}</b><br>{{company.address}}</p><p style=\"margin-top:18px\">Dear {{signatory.salutation}}:</p><p style=\"text-align:justify;text-indent:3em;line-height:1.6\">The attached Purchase Order No. <u>{{po.no}}</u> Dated <u>{{po.date}}</u> having been approved. Notice is hereby given to <b>{{company.name_upper}}</b> on the <b>{{project.title}}</b> and may proceed immediately to the delivery of the items enumerated therein within the specified delivery schedule.</p><p style=\"text-align:justify;line-height:1.6\">Please acknowledge receipt and acceptance of this notice by signing both copies in the space provided below and be guided accordingly.</p><div>{{signatories}}</div><table class=\"fx-plain fx-kv\" style=\"width:100%;margin-top:26px\"><tbody><tr><td class=\"k\" style=\"width:48%\">I acknowledge receipt of this Notice on</td><td>: <u>{{date.today}}</u></td></tr><tr><td class=\"k\">Name of the Representative of the Bidder</td><td>: <u>{{signatory.name}}</u></td></tr><tr><td class=\"k\">Authorized Signature</td><td>: _________________________</td></tr></tbody></table>','Legal','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":10,\"signatories\":[{\"lead\":\"Sincerely yours,\",\"name\":\"HON. {{entity.head_name_upper}}\",\"pos\":\"Barangay Chairman\",\"extra\":\"{{entity.location}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}',NULL,NULL,1,560,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(57,'bac_resolution','BAC resolution recommending the award','proforma','award','bac_resolution','Resolution of the Bids and Awards Committee recommending the award to the company (step 13 of the bidding), prepared for the signatures of the BAC and the Punong Barangay.','<div>{{letterhead}}</div><p style=\"text-align:center;margin:0\">Office of the Barangay</p><p style=\"text-align:center;margin:2px 0 2px\"><span style=\"font-size:13pt;font-weight:bold\">BIDS AND AWARDS COMMITTEE</span></p><p style=\"text-align:center;font-weight:bold;margin-bottom:18px\">RESOLUTION NO.__________</p><p style=\"text-align:justify;line-height:1.6\">WHEREAS, after a complete and final evaluation by the BAC Technical Working Group it was determined that <b>{{company.name_upper}}</b> has the CALCULATED RESPONSIVE BID for the {{project.title}} located at <b>{{entity.title_upper}}, {{entity.lgu_line_upper}}</b> for the Contract Price equivalent to <b>{{project.contract_price_text}}</b>.</p><p style=\"text-align:justify;line-height:1.6\">WHEREAS, the Approved Budget for the purchase is in the amount of <b>{{project.abc_text}}</b>.</p><p style=\"text-align:justify;line-height:1.6\">WHEREAS, the Bids and Awards Committee (BAC), through Resolution No.__________ dated______________ had recommended to the Barangay CHAIRMAN, <b>HON. {{entity.head_name_upper}}</b> to award the {{project.title}} located at {{entity.title_upper}}, {{entity.lgu_line_upper}}, to <b>{{company.name_upper}}</b> which recommendation was approved.</p><p style=\"text-align:justify;line-height:1.6\">NOW THEREFORE, we the members of the Bids and Awards Committee (BAC), hereby RESOLVED as it is hereby RESOLVED, to recommend to the Honorable Members, Barangay Council of {{entity.title}}, {{entity.city}}, to authorize <b>HON. {{entity.head_name_upper}}</b>, Barangay CHAIRMAN of {{entity.title_upper}}, {{entity.city}}, to enter into a Contract with <b>{{company.name_upper}}</b> at the Contract Price equivalent to <b>{{project.contract_price_text}}</b>.</p><p style=\"text-align:center;margin-top:14px\">{{entity.title}}, {{entity.city}}</p><div>{{signatories}}</div>','Legal','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":3,\"sig_top\":8,\"sig_space\":11,\"sig_gap\":6,\"signatories\":[{\"lead\":\"\",\"name\":\"HON. {{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_1_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_2_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_3_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_4_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_5_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.head_name_upper}}\",\"pos\":\"Barangay CHAIRMAN\",\"extra\":\"\",\"align\":\"center\",\"newrow\":1,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}',NULL,NULL,1,570,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL),
(58,'certificate_of_completion','Certificate of completion','proforma','closeout','completion_cert','Certificate of completion signed by the inspector and the Barangay Captain.','<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:16px 0\">CERTIFICATE OF COMPLETION</div><p>This is to certify that <b>{{company.name}}</b> has satisfactorily completed / delivered <b>{{project.title}}</b> under {{project.contract_ref}} for the <b>{{entity.name}}</b> in accordance with the specifications, in the amount of <b>{{project.contract_amount}}</b>.</p><p>Date of completion: <b>{{project.completion_date}}</b></p><p>Issued this ____ day of __________ for whatever legal purpose it may serve.</p><div>{{signatories}}</div>','A4','portrait',0,NULL,NULL,'entity.name,project.title',0,'layout','{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":14,\"signatories\":[{\"lead\":\"Inspected by:\",\"name\":\"{{project.inspector_upper}}\",\"pos\":\"Inspector\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Approved by:\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"Barangay Captain\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}',NULL,NULL,1,580,1,0,NULL,'2026-11-10 02:59:42',NULL,NULL);
INSERT INTO `brgy_template_versions` (`id`,`template_id`,`version_no`,`name`,`body`,`layout_json`,`positions_json`,`change_note`,`changed_by`,`changed_at`) VALUES
(1,1,1,'Cover letter: submission of bid / quotation','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Submission of bid / quotation for {{project.title}} ({{project.reference_no}})</b></p><p>Dear Sir / Madam:</p><p>In response to your invitation, {{company.name}} respectfully submits its bid / quotation for <b>{{project.title}}</b> in the total amount of <b>{{project.bid_amount}}</b> ({{project.bid_amount_words}}), inclusive of all applicable taxes, under the terms and specifications of your request.</p><p>Enclosed are the documents your request asks for, as listed in our checklist:</p>{{requirements.table}}<p>Our offer is valid for the period stated in your bidding documents. For clarifications, please contact the undersigned at {{company.phone}} or {{company.email}}.</p><div>{{signatories}}</div>',NULL,NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(2,2,1,'Company profile','<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">COMPANY PROFILE</h2><table class=\"ft\"><tbody><tr><td style=\"width:34%\">Registered name</td><td><b>{{company.name}}</b></td></tr><tr><td>Business address</td><td>{{company.address}}</td></tr><tr><td>Registration</td><td>{{company.reg_no}}</td></tr><tr><td>TIN / tax status</td><td>{{company.tin}}   ({{company.vat_status}})</td></tr><tr><td>PhilGEPS registration</td><td>{{company.philgeps_no}}   {{company.philgeps_class}}</td></tr><tr><td>Contact</td><td>{{company.phone}}   {{company.email}}</td></tr><tr><td>Authorized representative</td><td>{{signatory.name}}, {{signatory.position}}</td></tr></tbody></table><h3>Lines of business</h3><p>Supply and delivery of office, school, medical and household supplies, IT equipment and furniture; general services (janitorial, maintenance, repairs); and, through its licensed construction arm, minor infrastructure works for barangays and local government units.</p><h3>Facilities and people</h3><p>[Describe the warehouse, delivery vehicles, technical staff and the after-sales service offered.]</p><h3>Major government clients</h3><p>[List recent contracts: entity, project, amount, date completed.]</p>',NULL,NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(3,3,1,'Price quotation','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PRICE QUOTATION</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>We offer to supply the following under the terms of your request for quotation:</p>{{lines.table}}<p><b>Total amount: {{lines.total}}</b> ({{lines.total_words}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Delivery period</td><td>{{project.delivery_days}} from receipt of the purchase order / notice to proceed</td></tr><tr><td>Delivery site</td><td>{{project.delivery_site}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr><tr><td>Payment terms</td><td>{{project.payment_terms}}</td></tr><tr><td>Validity of the offer</td><td>As stated in the RFQ</td></tr></tbody></table><p>Prices include all applicable taxes, delivery and handling. We confirm that the items offered comply with the specifications stated in your request.</p><div>{{signatories}}</div>','{\"signatories\":[{\"lead\":\"Submitted by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(4,4,1,'Price schedule / bill of quantities','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PRICE SCHEDULE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p></p>{{lines.table}}<p><b>Total bid price: {{lines.total}}</b><br>({{lines.total_words}})</p><p>Name of bidder: <b>{{company.name}}</b><br>Signature of the authorized representative:</p><div>{{signatories}}</div>','{\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(5,5,1,'Technical proposal and statement of compliance','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">TECHNICAL PROPOSAL AND STATEMENT OF COMPLIANCE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>We state below, item by item, our compliance with the technical specifications. Where \"Comply\" is stated, the offer meets or exceeds the requirement; supporting brochures and data sheets are attached.</p><table class=\"ft\"><thead><tr><th style=\"width:6%\">Item</th><th>Specification required</th><th style=\"width:30%\">Offer (brand, model, specification)</th><th style=\"width:12%\">Statement</th></tr></thead><tbody><tr><td>1</td><td>{{project.specs}}</td><td>[Brand / model offered]</td><td>Comply</td></tr></tbody></table><p><b>Delivery:</b> {{project.delivery_days}} at {{project.delivery_site}}. <b>Warranty:</b> {{project.warranty_months}}.</p><div>{{signatories}}</div>','{\"signatories\":[{\"lead\":\"Certified correct:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(6,6,1,'Method statement (works / services)','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">METHOD STATEMENT</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><h3>1. Scope</h3><p>{{project.specs}}</p><h3>2. Mobilization</h3><p>[Site set-up, permits, coordination with the barangay and the end-user ({{project.end_user}}).]</p><h3>3. Sequence of work</h3><ol><li>[Activity]</li><li>[Activity]</li><li>[Activity]</li></ol><h3>4. Manpower and equipment</h3><p>[List of key personnel and equipment.]</p><h3>5. Quality control and testing</h3><p>[Tests, inspections and hold points; acceptance by the entity\'s inspection committee.]</p><h3>6. Safety and environment</h3><p>[Safety plan, signage, housekeeping, disposal.]</p><h3>7. Schedule</h3><p>Completion within {{project.delivery_days}} from the notice to proceed.</p><div>{{signatories}}</div>','{\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(7,7,1,'Implementation / delivery schedule','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">IMPLEMENTATION / DELIVERY SCHEDULE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><table class=\"ft\"><thead><tr><th style=\"width:6%\">No.</th><th>Activity / delivery</th><th style=\"width:18%\">Start</th><th style=\"width:18%\">Finish</th><th style=\"width:16%\">Weight %</th></tr></thead><tbody><tr><td>1</td><td>Mobilization / receipt of PO or NTP</td><td>Day 1</td><td>Day 3</td><td>5</td></tr><tr><td>2</td><td>[Delivery / work package]</td><td></td><td></td><td></td></tr><tr><td>3</td><td>Inspection and acceptance</td><td></td><td></td><td></td></tr></tbody></table><p>Total contract period: {{project.delivery_days}}.</p><div>{{signatories}}</div>','{\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(8,8,1,'Supply and services proposal','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SUPPLY AND SERVICES PROPOSAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>{{company.name}} proposes to supply and deliver the items below, together with the related services described, for <b>{{lines.total}}</b>.</p>{{lines.table}}<h3>Related services</h3><ul><li>Delivery, unloading and installation at {{project.delivery_site}}</li><li>Orientation of the end-users</li><li>Warranty service: {{project.warranty_months}}</li></ul><div>{{signatories}}</div>',NULL,NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(9,9,1,'Scope-of-work proposal','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SCOPE-OF-WORK PROPOSAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><h3>Scope of work</h3><p>{{project.specs}}</p><h3>Deliverables</h3><ul><li>[Deliverable]</li><li>[Deliverable]</li></ul><h3>Exclusions</h3><p>[Items not included.]</p><h3>Price</h3>{{lines.table}}<p>Duration: {{project.delivery_days}}. Payment: {{project.payment_terms}}.</p><div>{{signatories}}</div>',NULL,NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(10,10,1,'Request for quotation to a supplier / subcontractor','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">REQUEST FOR QUOTATION (SUPPLIER / SUBCONTRACTOR)</h2><p>To: [Supplier / subcontractor]<br>Address: [Address]</p><p>We are preparing an offer for <b>{{project.title}}</b> for {{entity.name}}. Please quote your best price and delivery for the following, valid for at least 30 days:</p>{{lines.table}}<p>Please include with your quotation: your business permit, BIR registration, product certifications or licenses, warranty terms and delivery lead time. Prices to us are separate from our prices to the procuring entity; this request does not disclose the entity\'s budget.</p><p>Reply to {{project.preparer}} at {{company.email}} by [date].</p><div>{{signatories}}</div>','{\"signatories\":[{\"lead\":\"Requested by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}',NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(11,11,1,'Internal bid approval sheet','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">INTERNAL BID APPROVAL SHEET</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project no.</td><td>{{project.no}}</td></tr><tr><td>Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode / law</td><td>{{project.mode}}, {{project.regime}}</td></tr><tr><td>ABC</td><td>{{project.abc}}</td></tr><tr><td>Bid amount</td><td><b>{{project.bid_amount}}</b></td></tr><tr><td>Bid deadline</td><td>{{project.bid_deadline}}</td></tr></tbody></table><h3>Costing and margin (confidential)</h3>{{costing.table}}<h3>Compliance checklist</h3>{{requirements.table}}<h3>Remarks</h3><p>[Risks, assumptions, supplier quotations relied on, payment record of the entity.]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.preparer}}</div><div>Prepared by</div></td><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.checker}}</div><div>Checked by</div></td><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>',NULL,NULL,'Supplied with the program',NULL,'2026-11-10 02:59:42'),
(12,12,1,'Contract review sheet','<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">CONTRACT REVIEW SHEET</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b> ({{project.no}})</td></tr><tr><td>Notice of award</td><td>{{project.noa_ref}}, {{project.noa_date}}</td></tr><tr><td>Contract / PO no.</td><td>{{project.contract_ref}}</td></tr><tr><td>Amount awarded</td><td>{{project.contract_amount}}</td></tr><tr><td>Delivery / completion</td><td>{{project.delivery_days}}; due {{project.due_date}}</td></tr><tr><td>Retention</td><td>{{project.retention_pct}}</td></tr><tr><td>Liquidated damages</td><td>{{project.ld_rate}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr><tr><td>Payment terms</td><td>{{project.payment_terms}}</td></tr></tbody></table><h3>Checks</h3><table class=\"ft\"><thead><tr><th>Point</th><th style=\"width:16%\">OK</th><th style=\"width:36%\">Remarks</th></tr></thead><tbody><tr><td>Items, quantities and prices agree with the approved bid</td><td></td><td></td></tr><tr><td>Delivery period and site can be met</td><td></td><td></td></tr><tr><td>Performance security / warranty requirements understood</td><td></td><td></td></tr><tr><td>Billing documents and payment terms understood</td><td></td><td></td></tr><tr><td>Taxes to be withheld by the entity noted</td><td></td><td></td></tr></tbody></table><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.checker}}</div><div>Reviewed by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>',NULL,NULL,'Supplied with the program',NUL